// Observed Antigravity wrapper output cap, not an underlying model capability.
// Keep this bridge-local: Antigravity currently caps visible output around 16K.
// See: https://github.com/keisksw/antigravity-output-analysis
const ANTIGRAVITY_CLAUDE_MAX_OUTPUT_TOKENS = 16_384;

// Gemini built-in tool names that Antigravity's v1internal endpoint rejects with a
// 400 when they are mixed with functionDeclarations in the same request. These must
// be stripped from the Cloud Code envelope's functionDeclarations.
const GEMINI_BUILTIN_TOOL_NAMES = new Set<string>([
  "google_search",
  "web_search",
  "search_web",
  "googleSearch",
]);

type GeminiPart = Record<string, unknown>;
type GeminiContent = { role: string; parts: GeminiPart[] };

type GeminiFunctionDeclaration = {
  name: string;
  description: string;
  parameters: unknown;
};

type GeminiFunctionCallingConfig = {
  mode: string;
  allowedFunctionNames?: string[];
};

type GeminiRequest = {
  model: string;
  contents?: GeminiContent[];
  [key: string]: unknown;
  generationConfig: GeminiGenerationConfig;
  safetySettings?: unknown;
  systemInstruction?: GeminiContent;
  tools?: Array<{
    functionDeclarations?: GeminiFunctionDeclaration[];
    googleSearch?: Record<string, unknown>;
  }>;
  toolConfig?: { functionCallingConfig: GeminiFunctionCallingConfig };
  cachedContent?: string;
  _toolNameMap?: Map<string, string>;
};

// Convert OpenAI tool_choice into Gemini's functionCallingConfig mode. Mirrors
// convertOpenAIToolChoice in openai-to-claude.ts (same enum shapes from the client).
// Gemini's modes: AUTO (model decides), ANY (must call a function — OpenAI's
// "required"), NONE (never call), VALIDATED (may call a function OR respond with
// plain text, but any call it makes is schema-validated — this was the unconditional
// hardcoded default before tool_choice was wired up at all, so it stays the fallback
// for "auto"/unset to avoid changing existing behavior for the common case).
//
// Live investigation: gemini-3.1-flash-lite frequently narrates an intended tool call
// in plain text ("I'm running python3 now...") instead of actually emitting one
// (dashboard log id 1784591483850-49c408) — VALIDATED mode never forces a call, so
// the model is always free to just talk instead of act. tool_choice: "required" (->
// ANY) is the lever a caller has to prevent that, but it was silently ignored until
// this fix — body.tool_choice was never read anywhere in this file.
function convertOpenAIToolChoiceToGemini(choice: unknown): GeminiFunctionCallingConfig {
  if (!choice) return { mode: "VALIDATED" };
  if (typeof choice === "string") {
    if (choice === "none") return { mode: "NONE" };
    if (choice === "required" || choice === "any") return { mode: "ANY" };
    return { mode: "VALIDATED" }; // "auto" or unrecognized string
  }
  if (typeof choice === "object") {
    const c = choice as { type?: string; function?: { name?: string } };
    if (c.type === "function" && c.function?.name) {
      return { mode: "ANY", allowedFunctionNames: [c.function.name] };
    }
    if (c.type === "none") return { mode: "NONE" };
    if (c.type === "required" || c.type === "any") return { mode: "ANY" };
  }
  return { mode: "VALIDATED" };
}

type CloudCodeEnvelope = {
  project: string;
  model?: string;
  user_prompt_id?: string;
  userAgent?: string;
  requestId?: string;
  requestType?: string;
  enabledCreditTypes?: string[];
  request: {
    session_id?: string;
    sessionId?: string;
    contents?: GeminiContent[];
    [key: string]: unknown;
    systemInstruction?: GeminiContent;
    generationConfig: GeminiGenerationConfig;
    tools?: Array<{
      functionDeclarations?: GeminiFunctionDeclaration[];
      googleSearch?: Record<string, unknown>;
    }>;
    safetySettings?: unknown;
    toolConfig?: {
      functionCallingConfig: { mode: string };
    };
  };
  _toolNameMap?: Map<string, string>;
};

type GeminiToolNameOptions = {
  stripNamespace?: boolean;
  signatureNamespace?: string | null;
  signaturelessToolCallMode?: "native" | "text" | "context";
  // Vertex AI's FunctionCall/FunctionResponse protos have no `id` field; emitting it
  // makes Vertex reject the request with 400 "Unknown name id" (#3440). The public
  // Gemini API DOES use `id` for Gemini 3+ signature matching, so this is scoped to
  // the vertex provider only.
  stripFunctionCallId?: boolean;
  /** Antigravity supports the thoughtSignature field. Standard Gemini rejects it with 400. */
  supportsSignatureBypass?: boolean;
};

// Gemini-family APIs (incl. Antigravity / Vertex) reject a `contents[]` array that
// has two adjacent entries with the same role:
//   400 INVALID_ARGUMENT "Request contains consecutive messages with the same role".
// Client history that carries consecutive user turns — or a tool-result turn (mapped
// to role:"user") immediately followed by a plain user turn — would otherwise leak
// that invalid alternation through. Merge adjacent same-role entries by concatenating
// their parts, the same normalization the Kiro and Claude request paths already apply
// (9router#2191).
export function mergeConsecutiveSameRoleContents(contents: GeminiContent[]): GeminiContent[] {
  const merged: GeminiContent[] = [];
  for (const entry of contents) {
    const last = merged[merged.length - 1];
    if (last && last.role === entry.role) {
      last.parts.push(...entry.parts);
    } else {
      // Shallow-copy the entry and its `parts` array so a later same-role merge
      // (`last.parts.push(...)`) never mutates the caller's input objects.
      merged.push({ ...entry, parts: [...entry.parts] });
    }
  }
  return merged;
}

// Core: Convert OpenAI request to Gemini format (base for all variants)
function openaiToGeminiBase(
  model: string,
  body: Record<string, unknown>,
  stream: boolean,
  toolNameOptions: GeminiToolNameOptions = {}
) {
  const result: GeminiRequest = {
    model: model,
    contents: [],
    generationConfig: {},
    safetySettings: body.safetySettings || DEFAULT_SAFETY_SETTINGS,
  };
  const toolNameMap = new Map<string, string>();
  const sanitizeToolName = (name: string) =>
    sanitizeGeminiToolName(name, {
      ...toolNameOptions,
      toolNameMap,
    });

  // Preserve cachedContent if provided by client (for explicit Gemini caching)
  if (body.cachedContent) {
    result.cachedContent = body.cachedContent as string;
  }

  // Generation config
  if (body.temperature !== undefined) {
    result.generationConfig.temperature = body.temperature;
  }
  if (body.top_p !== undefined) {
    result.generationConfig.topP = body.top_p;
  }
  if (body.top_k !== undefined) {
    result.generationConfig.topK = body.top_k;
  }
  if (body.stop !== undefined) {
    result.generationConfig.stopSequences = Array.isArray(body.stop) ? body.stop : [body.stop];
  }
  const maxOutputTokens = capMaxOutputTokens(
    model,
    (body.max_tokens ?? body.max_completion_tokens) as number | undefined
  );
  if (maxOutputTokens !== null) {
    result.generationConfig.maxOutputTokens = maxOutputTokens;
  }

  // Thinking / Reasoning support (Google Gemini 2.0+ Thinking models)
  // gemma-4 models return - 400: Thinking budget is not supported for this model.
  // Mirrors the same guard in claude-to-gemini.ts. Port of the thinkingConfig
  // guard half of decolua/9router#2480 (the signature-replay half of that PR
  // is out of scope and not ported here).
  if (model.startsWith("gemma-4")) {
    // gemma-4 models returns - 400: Thinking budget is not supported for this model
  } else {
    // 1. OpenAI format: reasoning_effort (none/low/medium/high/auto/max/xhigh)
    // "auto", "max", and "xhigh" are clamped to the high-tier budget because Gemini
    // does not accept these strings directly. "auto" signals "use max reasonable effort"
    // which maps to high. "max"/"xhigh" exceed Gemini's accepted range and are clamped.
    // "none" maps to budget 0 — an explicit, documented off-switch (#6813 defect 2),
    // distinct from the no-knob-at-all default-injection case below (#4170).
    // Port of decolua/9router#2043 by @nguyenxvotanminh3.
    if (body.reasoning_effort) {
      const highBudget = capThinkingBudget(model, 32768);
      const budgetMap: Record<string, number> = {
        none: 0,
        low: capThinkingBudget(model, 1024),
        medium: capThinkingBudget(model, getDefaultThinkingBudget(model) || 8192),
        high: highBudget,
        auto: highBudget,
        max: highBudget,
        xhigh: highBudget,
      };
      const budget =
        budgetMap[body.reasoning_effort as string] ??
        capThinkingBudget(model, getDefaultThinkingBudget(model) ?? 8192);
      // Always send thinkingConfig on this path — including for models with
      // thinkingBudgetCap:0 (e.g. gemini-3-flash), where the cap collapses the
      // requested budget down to 0. Omitting thinkingConfig entirely here regressed
      // the pre-#6943 native-defaults contract (thinkingBudget 0 / includeThoughts
      // false must still be present) and crashed callers that read
      // .thinkingConfig.thinkingBudget unconditionally.
      result.generationConfig.thinkingConfig = {
        thinkingBudget: budget,
        includeThoughts: budget !== 0,
      };
    }
    // 2. Claude format: thinking (type: enabled, budget_tokens)
    // Use an explicit numeric check (not truthy) so an explicit `budget_tokens: 0` — the
    // natural way to disable thinking — is honored as thinkingBudget 0 instead of being
    // dropped and falling through to the default injection below (#6813). A zero budget
    // yields no thoughts, so includeThoughts is only set for a non-zero budget.
    const thinking = body.thinking as { type?: string; budget_tokens?: number } | undefined;
    if (thinking?.type === "enabled" && typeof thinking.budget_tokens === "number") {
      // typeof check ensures only numeric budget_tokens triggers thinking path;
      // non-numeric values (e.g. string "auto") fall through to the effort-based path.
      const cappedBudget = capThinkingBudget(model, thinking.budget_tokens);
      // Only send thinkingConfig if the model supports thinking via budget.
      // Models with thinkingBudgetCap:0 (e.g. gemini-3-flash) reject
      // thinkingConfig even when capped to 0. The supportsThinking flag
      // tracks thinkingLevel support, not thinkingBudget; use thinkingBudgetCap
      // as the reliable indicator (gemini-2.5-flash has supportsThinking:false
      // but thinkingBudgetCap:24576, meaning it supports thinking via budget).
      // Models not in MODEL_SPECS (thinkingBudgetCap=undefined) default to allowed.
      if (cappedBudget > 0 || getModelSpec(model)?.thinkingBudgetCap !== 0) {
        result.generationConfig.thinkingConfig = {
          thinkingBudget: cappedBudget,
          includeThoughts: cappedBudget !== 0,
        };
      }
    }
  }

  // 3. Default: all modern Gemini models (2.5+) have thinking capability.
  // If the client didn't explicitly request thinking (via reasoning_effort or
  // thinking.type), still set includeThoughts so the upstream marks thought
  // parts with thought:true. Without this, the model's reasoning leaks into
  // visible content instead of being routed to reasoning_content by the
  // response translator. (#4170) — this default-injection case is intentionally
  // unconditional (no-knob-at-all still gets includeThoughts:true); the explicit
  // "reasoning_effort: none" off-switch above (#6813) is the supported opt-out.
  if (!result.generationConfig.thinkingConfig) {
    const modelLower = model.toLowerCase();
    if (
      modelLower.includes("gemini") &&
      !modelLower.includes("gemini-1") &&
      (!modelLower.includes("gemini-2.0") || modelLower.includes("thinking")) &&
      // Skip thinkingConfig for models that don't support thinking via budget.
      // Models with thinkingBudgetCap:0 (e.g. gemini-3-flash) reject
      // thinkingConfig. Use thinkingBudgetCap (not supportsThinking) as the
      // reliable indicator; gemini-2.5-flash has supportsThinking:false but
      // thinkingBudgetCap:24576, meaning it supports thinking via budget.
      // Models not in MODEL_SPECS (thinkingBudgetCap=undefined) default to allowed.
      getModelSpec(model)?.thinkingBudgetCap !== 0
    ) {
      result.generationConfig.thinkingConfig = {
        thinkingBudget: getDefaultThinkingBudget(model) || capThinkingBudget(model, 24576),
        includeThoughts: true,
      };
    }
  }

  // Build tool_call_id -> name map
  const tcID2Name: Record<string, string> = {};
  // #7752: strip any non-trailing tool_call whose id has no matching tool_result
  // anywhere in history — same guard `BaseExecutor.execute()` applies for the mainline
  // Claude path (#2382/#4714) and `antigravityToOpenAIRequest` applies for the mirror
  // incoming direction (#6026). Without this, an orphaned tool_call (e.g. left behind by
  // OpenCode's known abort/cancel bug) reaches Google's Cloud Code envelope as an unpaired
  // functionCall, which Vertex's Claude backend rejects with HTTP 400.
  const rawMessages = body.messages as Array<Record<string, unknown>> | undefined;
  const messages =
    rawMessages && Array.isArray(rawMessages)
      ? (fixToolPairs(rawMessages) as Array<Record<string, unknown>>)
      : rawMessages;
  if (messages && Array.isArray(messages)) {
    for (const msg of messages) {
      const toolCalls = msg.tool_calls as Array<Record<string, unknown>> | undefined;
      if (msg.role === "assistant" && toolCalls) {
        for (const tc of toolCalls) {
          const fn = tc.function as { name?: string } | undefined;
          if (tc.type === "function" && tc.id && fn?.name) {
            tcID2Name[tc.id as string] = fn.name;
          }
        }
      }
    }
  }

  // Build tool responses cache
  const toolResponses: Record<string, unknown> = {};
  if (messages && Array.isArray(messages)) {
    for (const msg of messages) {
      if (msg.role === "tool" && msg.tool_call_id) {
        toolResponses[msg.tool_call_id as string] = msg.content;
      }
    }
  }

  // Convert messages
  if (messages && Array.isArray(messages)) {
    for (const msg of messages) {
      const role = msg.role;
      const content = msg.content;

      if (role === "system" && messages.length > 1) {
        const systemText = typeof content === "string" ? content : extractTextContent(content);
        if (systemText) {
          if (!result.systemInstruction) {
            result.systemInstruction = {
              role: "system",
              parts: [{ text: systemText }],
            };
          } else {
            result.systemInstruction.parts.push({ text: systemText });
          }
        }
      } else if (role === "user" || (role === "system" && messages.length === 1)) {
        const parts = convertOpenAIContentToParts(content);
        if (parts.length > 0) {
          result.contents.push({ role: "user", parts });
        }
      } else if (role === "assistant") {
        const parts: GeminiPart[] = [];

        // Thinking/reasoning → thought part with signature
        if (msg.reasoning_content) {
          parts.push({
            thought: true,
            text: msg.reasoning_content,
          });
        }

        if (content) {
          const text = typeof content === "string" ? content : extractTextContent(content);
          if (text) {
            parts.push({ text });
          }
        }

        const toolCalls = msg.tool_calls as Array<Record<string, unknown>> | undefined;
        if (toolCalls && Array.isArray(toolCalls)) {
          const toolCallIds: string[] = [];
          const resolvedSignatures = new Map<string, string>();
          let firstPersistedSignature: string | undefined;
          for (const tc of toolCalls) {
            const id = tc.id as string;
            const resolved = resolveGeminiThoughtSignature(
              buildGeminiThoughtSignatureKey(toolNameOptions.signatureNamespace, id),
              extractClientThoughtSignature(tc)
            );
            if (typeof resolved === "string" && resolved.length > 0) {
              resolvedSignatures.set(id, resolved);
              firstPersistedSignature ??= resolved;
            }
          }

          let shouldUseEmbeddedSignature = !parts.some((p) => p.thoughtSignature);
          const signaturelessToolCallMode = toolNameOptions.signaturelessToolCallMode;
          const stringifySignaturelessToolCalls = signaturelessToolCallMode === "text";
          const contextualizeSignaturelessToolResponses =
            signaturelessToolCallMode === "text" || signaturelessToolCallMode === "context";

          for (const tc of toolCalls) {
            if (tc.type !== "function") continue;

            const id = tc.id as string;
            const fn = tc.function as { name: string; arguments?: string } | undefined;
            if (!fn) continue;

            const signatureForToolCall = resolvedSignatures.get(id);

            // Non-bypass paths (standard Gemini direct, mode "text"/"context")
            // cannot send a thoughtSignature and reject signature-less native tool
            // parts, so historical signature-less tool calls are represented as
            // inert text/context (#3358). The Antigravity/CLI bypass path
            // (supportsSignatureBypass) instead emits native parts carrying the
            // skip_thought_signature_validator sentinel below.
            if (!toolNameOptions.supportsSignatureBypass) {
              if (!signatureForToolCall && contextualizeSignaturelessToolResponses) {
                if (!toolCallIds.includes(id)) toolCallIds.push(id);
              }
              if (!signatureForToolCall && stringifySignaturelessToolCalls) {
                parts.push({
                  text: buildInertHistoricalToolCallText(fn.name, fn.arguments || "{}"),
                });
                continue;
              }
              if (!signatureForToolCall && signaturelessToolCallMode === "context") {
                continue;
              }
            }

            const args = tryParseJSON(fn.arguments || "{}");
            const embeddedThoughtSignature = shouldUseEmbeddedSignature
              ? firstPersistedSignature || signatureForToolCall
              : undefined;

            if (embeddedThoughtSignature) {
              shouldUseEmbeddedSignature = false;
            }

            // Gemini expects the signature on the functionCall part itself.
            // If we are in a mode where missing signatures cause 400s (and we couldn't find one),
            // safely default to the bypass string to protect against 400s.
            const finalSignature =
              embeddedThoughtSignature ||
              (toolNameOptions.supportsSignatureBypass && signaturelessToolCallMode !== "text"
                ? "skip_thought_signature_validator"
                : undefined);
            parts.push({
              ...(finalSignature ? { thoughtSignature: finalSignature } : {}),
              functionCall: {
                ...(toolNameOptions.stripFunctionCallId ? {} : { id: id }),
                name: sanitizeToolName(fn.name),
                args: args,
              },
            });

            // Bypass path always emits the native response; non-bypass keeps the
            // contextualize-aware bookkeeping (signature-less ids handled as text).
            if (
              toolNameOptions.supportsSignatureBypass ||
              !contextualizeSignaturelessToolResponses ||
              signatureForToolCall
            ) {
              toolCallIds.push(id);
            }
          }

          if (parts.length > 0) {
            result.contents.push({ role: "model", parts });
          }

          // Check if there are actual tool responses in the next messages
          const hasSignaturelessTextResponses =
            contextualizeSignaturelessToolResponses &&
            toolCalls.some((tc) => {
              const id = tc.id as string;
              return tc.type === "function" && !resolvedSignatures.has(id) && toolResponses[id];
            });
          const hasActualResponses =
            toolCallIds.some((fid) => toolResponses[fid]) || hasSignaturelessTextResponses;

          if (hasActualResponses) {
            const toolParts: GeminiPart[] = [];
            for (const fid of toolCallIds) {
              if (!toolResponses[fid]) continue;
              if (
                !toolNameOptions.supportsSignatureBypass &&
                contextualizeSignaturelessToolResponses &&
                !resolvedSignatures.has(fid)
              )
                continue;

              let name = tcID2Name[fid];
              if (!name) {
                const idParts = fid.split("-");
                if (idParts.length > 2) {
                  name = idParts.slice(0, -2).join("-");
                } else {
                  name = fid;
                }
              }
              name = sanitizeToolName(name);

              const resp = toolResponses[fid];
              let parsedResp = tryParseJSON(resp);
              if (parsedResp === null) {
                parsedResp = { result: resp };
              } else if (typeof parsedResp !== "object") {
                parsedResp = { result: parsedResp };
              }

              toolParts.push({
                functionResponse: {
                  ...(toolNameOptions.stripFunctionCallId ? {} : { id: fid }),
                  name: name,
                  response: { result: parsedResp },
                },
              });
            }

            if (
              !toolNameOptions.supportsSignatureBypass &&
              contextualizeSignaturelessToolResponses
            ) {
              // Signature-less historical tool responses are represented as text
              // so strict standard-Gemini endpoints don't reject them as native
              // functionResponse parts missing a matching thoughtSignature.
              // In context mode the matching historical functionCall is omitted,
              // avoiding pseudo tool-call records that Gemini Flash can repeat as
              // the visible final answer.
              for (const tc of toolCalls) {
                const id = tc.id as string;
                if (tc.type !== "function" || !id) continue;
                if (!resolvedSignatures.has(id) && toolResponses[id]) {
                  const fn = tc.function as { name?: string } | undefined;
                  const name = tcID2Name[id] || fn?.name || "unknown";
                  const resp = toolResponses[id];
                  toolParts.push({
                    text:
                      signaturelessToolCallMode === "text"
                        ? buildInertHistoricalToolResponseText(name, resp)
                        : buildHistoricalToolResultContext(name, resp),
                  });
                }
              }
            }

            if (toolParts.length > 0) {
              result.contents.push({ role: "user", parts: toolParts });
            }
          }
        } else if (parts.length > 0) {
          result.contents.push({ role: "model", parts });
        }
      }
    }
  }

  // Collapse any consecutive same-role contents Gemini would reject (9router#2191).
  result.contents = mergeConsecutiveSameRoleContents(result.contents ?? []);

  // Convert tools
  const bodyTools = body.tools as Array<Record<string, unknown>> | undefined;
  const geminiTools = buildGeminiTools(bodyTools, {
    ...toolNameOptions,
    toolNameMap,
  });

  // Support for Google Search grounding if requested via 'google_search' tool
  const hasGoogleSearch = bodyTools?.some((t) => {
    const fn = t.function as { name?: string } | undefined;
    return t.type === "function" && (fn?.name === "google_search" || fn?.name === "googleSearch");
  });

  type ToolEntry = NonNullable<GeminiRequest["tools"]>[number];

  if (geminiTools && geminiTools.length > 0) {
    result.tools = geminiTools;
    if (hasGoogleSearch) {
      result.tools.push({ googleSearch: {} });
    }
    result.toolConfig = {
      functionCallingConfig: convertOpenAIToolChoiceToGemini(body.tool_choice),
    };
  } else if (hasGoogleSearch) {
    result.tools = [{ googleSearch: {} }];
  }

  // Convert response_format to Gemini's responseMimeType/responseSchema
  const responseFormat = body.response_format as
    | {
        type?: string;
        json_schema?: { schema?: unknown; [key: string]: unknown };
      }
    | undefined;
  if (responseFormat) {
    if (responseFormat.type === "json_schema" && responseFormat.json_schema) {
      result.generationConfig.responseMimeType = "application/json";
      // Extract the schema (may be nested under .schema key)
      const schema = responseFormat.json_schema.schema || responseFormat.json_schema;
      if (schema && typeof schema === "object") {
        result.generationConfig.responseSchema = cleanJSONSchemaForAntigravity(schema);
      }
    } else if (responseFormat.type === "json_object") {
      result.generationConfig.responseMimeType = "application/json";
    } else if (responseFormat.type === "text") {
      result.generationConfig.responseMimeType = "text/plain";
    }
  }

  const changedToolNameMap = buildChangedToolNameMap(toolNameMap);
  if (changedToolNameMap) {
    result._toolNameMap = changedToolNameMap;
  }

  deepCleanUndefined(result);

  return result;
}

// OpenAI -> Gemini (standard API)
export function openaiToGeminiRequest(
  model: string,
  body: Record<string, unknown>,
  stream: boolean,
  credentials: Record<string, unknown> | null = null,
  options: {
    signaturelessToolCallMode?: "native" | "text" | "context";
  } = {}
) {
  // Thread the signature namespace so a thinking model's thoughtSignature (cached on the
  // response turn under `<connectionId>:<toolCallId>`) is found and re-attached to the
  // functionCall on the follow-up request. Without this the streaming lookup key didn't
  // match and Gemini rejected tool calls with 400 "missing thought_signature" (#2504).
  const signatureNamespace =
    credentials && typeof credentials["_signatureNamespace"] === "string"
      ? credentials["_signatureNamespace"]
      : null;
  return openaiToGeminiBase(model, body, stream, {
    signatureNamespace,
    signaturelessToolCallMode: options.signaturelessToolCallMode,
    stripFunctionCallId: isVertexGeminiProvider(credentials?._provider),
  });
}

// OpenAI -> Cloud Code Gemini payload used by Antigravity.
export function openaiToCloudCodeGeminiRequest(
  model: string,
  body: Record<string, unknown>,
  stream: boolean,
  options: {
    signatureNamespace?: string | null;
    signaturelessToolCallMode?: "native" | "text" | "context";
  } = {}
) {
  const request = openaiToGeminiBase(model, body, stream, {
    stripNamespace: true,
    signatureNamespace: options.signatureNamespace,
    signaturelessToolCallMode: options.signaturelessToolCallMode,
    supportsSignatureBypass: true,
  });

  // Standard Gemini requests retain the historical all-OFF defaults, but Cloud Code
  // must receive safety policy only when the caller explicitly supplied it.
  if (!Object.prototype.hasOwnProperty.call(body, "safetySettings")) {
    delete request.safetySettings;
  }

  return request;
}

function wrapInCloudCodeEnvelope(model, cloudCodeRequest, credentials = null) {
  // Fall back to providerSpecificData.projectId — some connections (and post-refresh
  // credentials) store it there rather than at the top level, which otherwise produced a
  // spurious 422 "Missing Google projectId" on the Antigravity /v1beta path (#2480).
  const providerSpecificProjectId = (
    credentials?.providerSpecificData as { projectId?: unknown } | undefined
  )?.projectId;
  let projectId =
    credentials?.projectId ||
    (typeof providerSpecificProjectId === "string" ? providerSpecificProjectId : "");

  if (!projectId) {
    console.warn(
      `[OmniRoute] Antigravity account is missing projectId. ` +
        `Attempting request with empty project — reconnect OAuth to resolve.`
    );
    projectId = "";
  }

  const cleanModel = model.includes("/") ? model.split("/").pop()! : model;

  const envelope: CloudCodeEnvelope = {
    project: projectId,
    requestId: generateAntigravityRequestId(),
    request: {
      sessionId: getAntigravitySessionId(credentials),
      contents: cloudCodeRequest.contents,
      systemInstruction: cloudCodeRequest.systemInstruction,
      generationConfig: applyAntigravityGenerationDefaults(cloudCodeRequest.generationConfig),
      tools: cloudCodeRequest.tools,
      safetySettings: cloudCodeRequest.safetySettings,
    },
    model: cleanModel,
    userAgent: getAntigravityEnvelopeUserAgent(credentials),
    requestType: "agent",
  };
  if (cloudCodeRequest._toolNameMap instanceof Map && cloudCodeRequest._toolNameMap.size > 0) {
    envelope._toolNameMap = cloudCodeRequest._toolNameMap;
  }

  const defaultPart: GeminiPart = { text: ANTIGRAVITY_DEFAULT_SYSTEM };
  if (envelope.request.systemInstruction?.parts) {
    envelope.request.systemInstruction.parts.unshift(defaultPart);
  } else {
    envelope.request.systemInstruction = { role: "system", parts: [defaultPart] };
  }

  // Strip Gemini built-in tool *names* out of functionDeclarations: Antigravity's
  // v1internal endpoint returns 400 when a built-in tool (google_search etc.) is
  // mixed with functionDeclarations in the same request. Native grounding entries
  // (e.g. `{ googleSearch: {} }`) are left intact; only the functionDeclarations
  // arrays are cleaned, and a declarations entry that becomes empty is dropped.
  if (envelope.request.tools && envelope.request.tools.length > 0) {
    const cleanedTools = envelope.request.tools
      .map((tool) => {
        if (!Array.isArray(tool.functionDeclarations)) {
          return tool;
        }
        const customDecls = tool.functionDeclarations.filter(
          (fn) => !GEMINI_BUILTIN_TOOL_NAMES.has(fn.name)
        );
        return { ...tool, functionDeclarations: customDecls };
      })
      .filter(
        (tool) => !Array.isArray(tool.functionDeclarations) || tool.functionDeclarations.length > 0
      );
    envelope.request.tools = cleanedTools.length > 0 ? cleanedTools : undefined;
  }

  const hasCustomTools = envelope.request.tools?.some(
    (tool) => (tool.functionDeclarations?.length ?? 0) > 0
  );
  if (hasCustomTools) {
    // Reuse the toolConfig openaiToGeminiBase already computed from the caller's
    // tool_choice (cloudCodeRequest is that function's return value) instead of
    // re-deriving a hardcoded default here — see convertOpenAIToolChoiceToGemini.
    envelope.request.toolConfig = cloudCodeRequest.toolConfig ?? {
      functionCallingConfig: { mode: "VALIDATED" },
    };
  }

  return envelope;
}

function getAntigravityClaudeOutputTokens(body: Record<string, unknown>): number {
  const requested = body.max_tokens ?? body.max_completion_tokens;
  if (typeof requested === "number" && Number.isFinite(requested) && requested >= 1) {
    return Math.min(Math.floor(requested), ANTIGRAVITY_CLAUDE_MAX_OUTPUT_TOKENS);
  }
  return ANTIGRAVITY_CLAUDE_MAX_OUTPUT_TOKENS;
}

// OpenAI -> Antigravity (Sandbox Cloud Code with wrapper)
export function openaiToAntigravityRequest(model, body, stream, credentials = null) {
  const isClaude = model.toLowerCase().includes("claude");
  // All modern Gemini models (2.5+, 3.x, pro-agent, etc.) use thinking by default
  // and require thought_signature for multi-turn tool calls.
  // Safe default: all non-Claude models via Antigravity are thinking Gemini.
  const modelLower = model.toLowerCase();
  const isThinkingGemini =
    !isClaude &&
    (modelLower.includes("thinking") ||
      modelLower.includes("gemini-3") ||
      modelLower.includes("gemini-2.5") ||
      modelLower.includes("gemini-pro"));
  const signatureNamespace =
    credentials &&
    typeof credentials === "object" &&
    typeof (credentials as Record<string, unknown>)._signatureNamespace === "string"
      ? ((credentials as Record<string, unknown>)._signatureNamespace as string)
      : null;
  const cloudCodeRequest = openaiToCloudCodeGeminiRequest(model, body, stream, {
    signatureNamespace,
    signaturelessToolCallMode: isThinkingGemini ? "context" : "native",
  });

  if (isClaude) {
    cloudCodeRequest.generationConfig.maxOutputTokens = getAntigravityClaudeOutputTokens(body);
  }

  const envelope = wrapInCloudCodeEnvelope(model, cloudCodeRequest, credentials);

  // Match real Antigravity client: don't send maxOutputTokens when the user
  // hasn't explicitly specified max_tokens / max_completion_tokens.
  // The Cloud Code server decides the output limit on its own.
  // Note: read hasThinking BEFORE stripping thinkingConfig below — for Claude
  // models the Cloud Code envelope still carries a thinkingBudget set upstream
  // by applyAntigravityGenerationDefaults, which we must consult here so we
  // do not accidentally drop the maxOutputTokens it bumped for us.
  const clientRequestedMaxTokens = body.max_tokens ?? body.max_completion_tokens;
  const hasThinking = !!envelope.request?.generationConfig?.thinkingConfig?.thinkingBudget;
  if (
    clientRequestedMaxTokens === undefined &&
    !hasThinking &&
    envelope.request?.generationConfig
  ) {
    delete envelope.request.generationConfig.maxOutputTokens;
  }

  // Claude models on Antigravity use their own native thinking — Gemini's thinkingConfig
  // is not understood by the Cloud Code Claude endpoint and must be stripped.
  // applyAntigravityGenerationDefaults (inside wrapInCloudCodeEnvelope) already bumped
  // maxOutputTokens to thinkingBudget+1 before we get here, so the budget is preserved.
  // Must run AFTER the hasThinking-derived maxOutputTokens decision above so the
  // budget is accounted for before the field is removed.
  if (isClaude && envelope.request?.generationConfig) {
    delete envelope.request.generationConfig.thinkingConfig;
  }

  return envelope;
}

// Register
register(
  FORMATS.OPENAI,
  FORMATS.GEMINI,
  (model, body, stream = false, credentials = null) =>
    openaiToGeminiRequest(model, body, stream, credentials, {
      signaturelessToolCallMode: "context",
    }),
  null
);
register(FORMATS.OPENAI, FORMATS.ANTIGRAVITY, openaiToAntigravityRequest, null);

import { getDbInstance } from "../../src/lib/db/core.ts";

const MAX_SIGNATURES = 1000;
const MAX_PERSISTED_SIGNATURES = 2_000;
const MEMORY_TTL_MS = 1000 * 60 * 60;
const PERSISTED_TTL_MS = 1000 * 60 * 60 * 24 * 30;
const NAMESPACE = "gemini_thought_signatures";

export type SignatureCacheMode = "enabled" | "bypass" | "bypass-strict";

type Entry = {
  signature: string;
  expiresAt: number;
};

type PersistedEntry = Entry & {
  createdAt: number;
};

const signatures = new Map<string, Entry>();
let signatureCacheMode: SignatureCacheMode = "enabled";
let persistedPruneCounter = 0;
const MAX_LOGGED_ERRORS = 50;
const loggedPersistenceErrors = new Set<string>();

function warnPersistenceError(operation: string, error: unknown) {
  if (process.env.NODE_ENV === "test") return;
  if (loggedPersistenceErrors.has(operation)) return;
  if (loggedPersistenceErrors.size >= MAX_LOGGED_ERRORS) {
    const first = loggedPersistenceErrors.values().next().value;
    if (first !== undefined) loggedPersistenceErrors.delete(first);
  }
  loggedPersistenceErrors.add(operation);
  const message = error instanceof Error ? error.message : String(error);
  console.warn(`[signature-cache] persisted ${operation} failed: ${message}`);
}

export function buildGeminiThoughtSignatureKey(namespace: unknown, toolCallId: unknown): unknown {
  if (
    typeof namespace === "string" &&
    namespace.length > 0 &&
    typeof toolCallId === "string" &&
    toolCallId.length > 0
  ) {
    return `${namespace}:${toolCallId}`;
  }
  return toolCallId;
}

function pruneExpired() {
  const now = Date.now();
  for (const [key, value] of signatures.entries()) {
    if (value.expiresAt <= now) {
      signatures.delete(key);
    }
  }

  while (signatures.size > MAX_SIGNATURES) {
    const oldestKey = signatures.keys().next().value;
    if (!oldestKey) break;
    signatures.delete(oldestKey);
  }
}

function serializePersistedEntry(entry: PersistedEntry): string {
  return JSON.stringify(entry);
}

function parsePersistedEntry(value: string, now = Date.now()) {
  try {
    const parsed = JSON.parse(value) as Partial<PersistedEntry>;
    if (typeof parsed.signature !== "string" || parsed.signature.length === 0) return null;
    const createdAt = typeof parsed.createdAt === "number" ? parsed.createdAt : now;
    const expiresAt =
      typeof parsed.expiresAt === "number" ? parsed.expiresAt : now + PERSISTED_TTL_MS;
    if (expiresAt <= now) return null;
    return {
      entry: { signature: parsed.signature, createdAt, expiresAt },
      shouldRewrite: createdAt !== parsed.createdAt || expiresAt !== parsed.expiresAt,
    };
  } catch {
    if (!value) return null;
    return {
      entry: {
        signature: value,
        createdAt: now,
        expiresAt: now + PERSISTED_TTL_MS,
      },
      shouldRewrite: true,
    };
  }
}

function maybePrunePersistedSignatures(db: ReturnType<typeof getDbInstance>) {
  persistedPruneCounter += 1;
  if (persistedPruneCounter % 100 !== 0) return;

  const rows = db
    .prepare("SELECT key, value FROM key_value WHERE namespace = ?")
    .all(NAMESPACE) as Array<{ key: string; value: string }>;

  const now = Date.now();
  const validRows: Array<{ key: string; createdAt: number }> = [];
  const keysToDelete = new Set<string>();

  for (const row of rows) {
    const parsed = parsePersistedEntry(row.value, now);
    if (!parsed) {
      keysToDelete.add(row.key);
      continue;
    }
    validRows.push({ key: row.key, createdAt: parsed.entry.createdAt });
  }

  if (rows.length <= MAX_PERSISTED_SIGNATURES && keysToDelete.size === 0) return;

  validRows.sort((a, b) => b.createdAt - a.createdAt);
  for (const row of validRows.slice(MAX_PERSISTED_SIGNATURES)) {
    keysToDelete.add(row.key);
  }

  if (keysToDelete.size === 0) return;
  const remove = db.prepare("DELETE FROM key_value WHERE namespace = ? AND key = ?");
  const tx = db.transaction((keys: string[]) => {
    for (const key of keys) remove.run(NAMESPACE, key);
  });
  tx([...keysToDelete]);
}

export function storeGeminiThoughtSignature(toolCallId: unknown, signature: unknown) {
  if (typeof toolCallId !== "string" || !toolCallId) return;
  if (typeof signature !== "string" || !signature) return;

  const now = Date.now();
  pruneExpired();
  signatures.set(toolCallId, {
    signature,
    expiresAt: now + MEMORY_TTL_MS,
  });

  try {
    const db = getDbInstance();
    db.prepare("INSERT OR REPLACE INTO key_value (namespace, key, value) VALUES (?, ?, ?)").run(
      NAMESPACE,
      toolCallId,
      serializePersistedEntry({ signature, createdAt: now, expiresAt: now + PERSISTED_TTL_MS })
    );
    maybePrunePersistedSignatures(db);
  } catch (error) {
    warnPersistenceError("store", error);
  }
}

export function getGeminiThoughtSignature(toolCallId: unknown) {
  if (typeof toolCallId !== "string" || !toolCallId) return null;

  pruneExpired();
  const entry = signatures.get(toolCallId);
  if (entry) return entry.signature;

  try {
    const db = getDbInstance();
    const row = db
      .prepare("SELECT value FROM key_value WHERE namespace = ? AND key = ?")
      .get(NAMESPACE, toolCallId) as { value: string } | undefined;

    if (row?.value) {
      const persisted = parsePersistedEntry(row.value);
      if (!persisted) {
        db.prepare("DELETE FROM key_value WHERE namespace = ? AND key = ?").run(
          NAMESPACE,
          toolCallId
        );
        return null;
      }

      signatures.set(toolCallId, {
        signature: persisted.entry.signature,
        expiresAt: Date.now() + MEMORY_TTL_MS,
      });

      if (persisted.shouldRewrite) {
        db.prepare("UPDATE key_value SET value = ? WHERE namespace = ? AND key = ?").run(
          serializePersistedEntry(persisted.entry),
          NAMESPACE,
          toolCallId
        );
      }

      return persisted.entry.signature;
    }
  } catch (error) {
    warnPersistenceError("read", error);
  }

  return null;
}

export function normalizeSignatureCacheMode(value: unknown): SignatureCacheMode {
  return value === "bypass" || value === "bypass-strict" ? value : "enabled";
}

export function setGeminiThoughtSignatureMode(mode: unknown) {
  signatureCacheMode = normalizeSignatureCacheMode(mode);
}

export function getGeminiThoughtSignatureMode(): SignatureCacheMode {
  return signatureCacheMode;
}

function decodeSignature(signature: string): Buffer | null {
  if (!signature || (signature[0] !== "R" && signature[0] !== "E")) return null;

  const payload = signature.slice(1);
  if (!/^[A-Za-z0-9+/]+={0,2}$/.test(payload) || payload.length % 4 === 1) {
    return null;
  }

  try {
    const decoded = Buffer.from(payload, "base64");
    if (decoded.length === 0) return null;

    const canonical = decoded.toString("base64").replace(/=+$/g, "");
    if (canonical !== payload.replace(/=+$/g, "")) {
      return null;
    }

    return decoded;
  } catch {
    return null;
  }
}

function readVarint(
  buffer: Buffer,
  startOffset: number
): { nextOffset: number; value: number } | null {
  let offset = startOffset;
  let result = 0;
  let shift = 0;

  while (offset < buffer.length && shift < 35) {
    const byte = buffer[offset];
    result |= (byte & 0x7f) << shift;
    offset += 1;

    if ((byte & 0x80) === 0) {
      return { nextOffset: offset, value: result };
    }

    shift += 7;
  }

  return null;
}

export function isValidBasicGeminiThoughtSignature(signature: unknown): boolean {
  if (typeof signature !== "string") return false;
  const decoded = decodeSignature(signature);
  return Boolean(decoded && decoded[0] === 0x12);
}

export function isValidFullGeminiThoughtSignature(signature: unknown): boolean {
  if (typeof signature !== "string") return false;
  const decoded = decodeSignature(signature);
  if (!decoded || decoded[0] !== 0x12) return false;

  const outerLength = readVarint(decoded, 1);
  if (!outerLength) return false;

  const outerEnd = outerLength.nextOffset + outerLength.value;
  if (outerEnd !== decoded.length) return false;

  const inner = decoded.subarray(outerLength.nextOffset, outerEnd);
  if (inner.length === 0 || inner[0] !== 0x0a) return false;

  const innerLength = readVarint(inner, 1);
  if (!innerLength) return false;

  return innerLength.nextOffset + innerLength.value === inner.length;
}

export function resolveGeminiThoughtSignature(
  toolCallId: unknown,
  clientSignature?: unknown
): string | null {
  const persisted = getGeminiThoughtSignature(toolCallId);
  if (typeof clientSignature !== "string" || clientSignature.length === 0) {
    return persisted;
  }

  if (signatureCacheMode === "enabled") {
    return persisted;
  }

  const isValid =
    signatureCacheMode === "bypass-strict"
      ? isValidFullGeminiThoughtSignature(clientSignature)
      : isValidBasicGeminiThoughtSignature(clientSignature);

  if (isValid) {
    return clientSignature;
  }

  console.warn(
    `[signature-cache] ${signatureCacheMode}: invalid client thought signature, falling back`
  );
  return persisted;
}

export function clearGeminiThoughtSignatures() {
  signatures.clear();
  signatureCacheMode = "enabled";
  try {
    const db = getDbInstance();
    db.prepare("DELETE FROM key_value WHERE namespace = ?").run(NAMESPACE);
  } catch (error) {
    warnPersistenceError("clear", error);
  }
}

export function clearGeminiThoughtSignatureMemoryForTests() {
  signatures.clear();
}

export function getGeminiThoughtSignatureMemorySizeForTests() {
  pruneExpired();
  return signatures.size;
}

import crypto from "node:crypto";

export type AntigravityCredentialsLike = {
  accessToken?: string | null;
  connectionId?: string | null;
  email?: string | null;
  projectId?: string | null;
  providerSpecificData?: Record<string, unknown> | null;
};

const FNV_OFFSET_I64 = -3750763034362895579n;
const FNV_PRIME_I64 = 1099511628211n;
function toNonEmptyString(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : null;
}

function getProviderDataString(
  credentials: AntigravityCredentialsLike | null | undefined,
  key: string
): string | null {
  const data = credentials?.providerSpecificData;
  return data && typeof data === "object" ? toNonEmptyString(data[key]) : null;
}

export function getAntigravityAccountKey(
  credentials?: AntigravityCredentialsLike | null
): string | null {
  return (
    toNonEmptyString(credentials?.email) ||
    getProviderDataString(credentials, "email") ||
    getProviderDataString(credentials, "accountId") ||
    toNonEmptyString(credentials?.connectionId) ||
    null
  );
}

export function getAntigravityEnvelopeUserAgent(
  _credentials?: AntigravityCredentialsLike | null
): "antigravity" {
  return "antigravity";
}

export function generateAntigravityRequestId(): string {
  return `agent/${Date.now()}/${crypto.randomBytes(4).toString("hex")}`;
}

export function generateAntigravitySessionId(): string {
  const max = 18446744073709551615n; // 2^64 - 1
  const target = 9_000_000_000_000_000_000n;
  // Rejection sampling: discard values in [limit, max] that would cause modulo bias.
  // Accepted range [0, limit) divides evenly by target, so value % target is uniform.
  const limit = max - (max % target);
  let value: bigint;
  do {
    value = crypto.randomBytes(8).readBigUInt64BE();
  } while (value >= limit);
  // lgtm[js/biased-cryptographic-random] — rejection sampling above eliminates bias
  return `-${(value % target).toString()}`; // nosemgrep: biased-cryptographic-random
}

export function deriveAntigravitySessionId(accountKey?: string | null): string | null {
  const key = toNonEmptyString(accountKey);
  if (!key) return null;

  let hash = FNV_OFFSET_I64;
  for (const byte of Buffer.from(key, "utf8")) {
    hash = BigInt.asIntN(64, hash ^ BigInt(byte));
    hash = BigInt.asIntN(64, hash * FNV_PRIME_I64);
  }
  return hash.toString();
}

export function getAntigravitySessionId(
  credentials?: AntigravityCredentialsLike | null,
  fallback?: unknown
): string {
  return (
    deriveAntigravitySessionId(getAntigravityAccountKey(credentials)) ||
    toNonEmptyString(fallback) ||
    generateAntigravitySessionId()
  );
}

/**
 * Context Manager — Phase 4
 *
 * Pre-flight context compression to prevent "prompt too long" errors.
 * 3 layers: trim tool messages, compress structured thinking, aggressive purification.
 */

import { REGISTRY } from "../config/providerRegistry.ts";
import { getModelContextLimit } from "../../src/lib/modelCapabilities.ts";
import { parseModel } from "./model.ts";
import { jsonLength } from "../utils/jsonSize.ts";

// Default token limits per provider (fallbacks when not in registry)
const DEFAULT_LIMITS: Record<string, number> = {
  claude: 200000,
  openai: 128000,
  gemini: 1000000,
  codex: 400000,
  // HyperAgent Claude-family agents (fable/opus/sonnet) — 1M default; was falling
  // through to 128k and blocking normal agentic tool loops with huge catalogs.
  hyperagent: 1_000_000,
  ha: 1_000_000,
  default: 128000,
};

// Environment variable overrides (highest priority)
function getEnvOverride(provider: string): number | null {
  const envKey = `CONTEXT_LENGTH_${provider.toUpperCase().replace(/[^A-Z0-9]/g, "_")}`;
  const envValue = process.env[envKey];
  if (envValue) {
    const parsed = parseInt(envValue, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  // Global override
  const globalValue = process.env.CONTEXT_LENGTH_DEFAULT;
  if (globalValue) {
    const parsed = parseInt(globalValue, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return null;
}

// Reserve tokens override from environment variable
function getReserveTokensOverride(): number | null {
  const envValue = process.env.CONTEXT_RESERVE_TOKENS;
  if (envValue) {
    const parsed = parseInt(envValue, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return null;
}

// How many of the newest inline images to keep when pruning older ones (#8560).
function getKeepLatestImagesOverride(): number | null {
  const envValue = process.env.CONTEXT_KEEP_LATEST_IMAGES;
  if (envValue) {
    const parsed = parseInt(envValue, 10);
    if (!isNaN(parsed) && parsed >= 0) return parsed;
  }
  return null;
}

const DEFAULT_KEEP_LATEST_IMAGES = 2;
const IMAGE_REMOVED_PLACEHOLDER = "[Earlier image removed to fit context window]";

// Rough chars-per-token ratio for quick estimation
const CHARS_PER_TOKEN = 4;

// Bounded per-image token budget used in place of measuring the raw base64
// payload as text. In line with the owner's PoC (~1052 total for prompt +
// 1 image) and litellm's calculate_img_tokens() default-count fast-path —
// see #8368 research notes.
const IMAGE_TOKEN_ESTIMATE = 1200;

// Matches inline base64 data URLs, e.g. "data:image/png;base64,AAAA...".
// Deliberately scoped to `data:image/...;base64,` so remote (http/https)
// URLs and generic long base64 text strings stay on the text-estimation path.
const INLINE_BASE64_IMAGE_RE = /^data:image\/[a-zA-Z0-9.+-]+;base64,/;

function isInlineBase64ImageUrl(value: unknown): boolean {
  return typeof value === "string" && INLINE_BASE64_IMAGE_RE.test(value);
}

// OpenAI chat.completions: { type: 'image_url', image_url: { url: 'data:...' } | 'data:...' }
function matchesOpenAIImageUrlShape(node: Record<string, unknown>): boolean {
  const imageUrl = node.image_url;
  if (isInlineBase64ImageUrl(imageUrl)) return true;
  return (
    !!imageUrl &&
    typeof imageUrl === "object" &&
    isInlineBase64ImageUrl((imageUrl as Record<string, unknown>).url)
  );
}

// AI SDK: { type: 'image', image: 'data:...' } (also covers Responses API's
// { type: 'input_image', image_url: 'data:...' } via matchesOpenAIImageUrlShape above).
function matchesAiSdkImageShape(node: Record<string, unknown>): boolean {
  return node.type === "image" && isInlineBase64ImageUrl(node.image);
}

// Claude: { type: 'image', source: { type: 'base64', data: '...' } }
function matchesClaudeSourceShape(node: Record<string, unknown>): boolean {
  if (node.type !== "image") return false;
  const source = node.source;
  if (!source || typeof source !== "object") return false;
  const src = source as Record<string, unknown>;
  return src.type === "base64" && typeof src.data === "string";
}

// Gemini: { inlineData: { data: '...' } } | { inline_data: { data: '...' } }
function matchesGeminiInlineDataShape(node: Record<string, unknown>): boolean {
  const inlineData = node.inlineData ?? node.inline_data;
  if (!inlineData || typeof inlineData !== "object") return false;
  return typeof (inlineData as Record<string, unknown>).data === "string";
}

/**
 * Detect the 5 documented inline-base64 image content-block shapes (see the
 * shape-specific matchers above).
 */
export function isInlineBase64ImageBlock(node: Record<string, unknown>): boolean {
  return (
    matchesOpenAIImageUrlShape(node) ||
    matchesAiSdkImageShape(node) ||
    matchesClaudeSourceShape(node) ||
    matchesGeminiInlineDataShape(node)
  );
}

function replaceImageBlockWithPlaceholder(block: Record<string, unknown>): Record<string, unknown> {
  // Responses API parts use input_text / input_image — keep that family so restore
  // does not rewrite a chat-completions-shaped part into a Responses input item.
  if (block.type === "input_image") {
    return { type: "input_text", text: IMAGE_REMOVED_PLACEHOLDER };
  }
  if (block.inlineData || block.inline_data) {
    return { text: IMAGE_REMOVED_PLACEHOLDER };
  }
  return { type: "text", text: IMAGE_REMOVED_PLACEHOLDER };
}

/**
 * Replace oldest inline base64 image blocks with short text placeholders while
 * keeping the newest `keepLatest` images intact. Vision models still receive
 * recent screenshots; older ones are dropped so multi-turn Codex/Responses
 * sessions can fit the concrete input cap (#8560).
 */
export function pruneOlderInlineImages(
  messages: Record<string, unknown>[],
  options: { keepLatest?: number; targetTokens?: number } = {}
): { messages: Record<string, unknown>[]; pruned: number } {
  const keepLatest =
    options.keepLatest ?? getKeepLatestImagesOverride() ?? DEFAULT_KEEP_LATEST_IMAGES;
  const targetTokens = options.targetTokens;

  const locations: Array<{ messageIndex: number; contentIndex: number }> = [];
  for (let messageIndex = 0; messageIndex < messages.length; messageIndex++) {
    const content = messages[messageIndex]?.content;
    if (!Array.isArray(content)) continue;
    for (let contentIndex = 0; contentIndex < content.length; contentIndex++) {
      const part = content[contentIndex];
      if (
        part &&
        typeof part === "object" &&
        !Array.isArray(part) &&
        isInlineBase64ImageBlock(part as Record<string, unknown>)
      ) {
        locations.push({ messageIndex, contentIndex });
      }
    }
  }

  if (locations.length <= keepLatest) {
    return { messages, pruned: 0 };
  }

  const prunable = locations.slice(0, Math.max(0, locations.length - keepLatest));
  const next = messages.map((message) => {
    if (!Array.isArray(message.content)) return message;
    return { ...message, content: [...message.content] };
  });
  let pruned = 0;

  for (const location of prunable) {
    if (targetTokens != null && estimateTokens(next) <= targetTokens) break;
    const content = next[location.messageIndex].content as unknown[];
    const block = content[location.contentIndex] as Record<string, unknown>;
    content[location.contentIndex] = replaceImageBlockWithPlaceholder(block);
    pruned += 1;
  }

  return { messages: next, pruned };
}

/**
 * Recursively walk a structured node, replacing every recognized inline
 * base64 image block with a short placeholder (so its bulk is excluded from
 * the char-count pass below) while accumulating a bounded per-image token
 * cost. Returns the accumulated image token cost; the caller measures the
 * placeholder-substituted structure with the normal char/4 heuristic.
 *
 * Non-image content (including remote image URLs and generic base64 text)
 * is left untouched and continues to flow through the text-estimation path.
 */
function extractImageTokens(node: unknown, seen: Set<unknown>): { node: unknown; tokens: number } {
  if (node === null || typeof node !== "object") {
    return { node, tokens: 0 };
  }
  // Guard against cycles in structured request bodies.
  if (seen.has(node)) return { node, tokens: 0 };
  seen.add(node);

  if (Array.isArray(node)) {
    let tokens = 0;
    const out = node.map((item) => {
      const record =
        item && typeof item === "object" && !Array.isArray(item)
          ? (item as Record<string, unknown>)
          : null;
      if (record && isInlineBase64ImageBlock(record)) {
        tokens += IMAGE_TOKEN_ESTIMATE;
        return { __image_token_estimate__: IMAGE_TOKEN_ESTIMATE };
      }
      const result = extractImageTokens(item, seen);
      tokens += result.tokens;
      return result.node;
    });
    return { node: out, tokens };
  }

  const record = node as Record<string, unknown>;
  if (isInlineBase64ImageBlock(record)) {
    return {
      node: { __image_token_estimate__: IMAGE_TOKEN_ESTIMATE },
      tokens: IMAGE_TOKEN_ESTIMATE,
    };
  }

  let tokens = 0;
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(record)) {
    const result = extractImageTokens(value, seen);
    out[key] = result.node;
    tokens += result.tokens;
  }
  return { node: out, tokens };
}

/**
 * Estimate token count from text length.
 *
 * Structured input is first walked for inline base64 image blocks (#8368):
 * each recognized image block is substituted with a bounded per-image token
 * budget instead of measuring its base64 payload as raw text, then the
 * remainder of the structure is measured normally via the char/4 heuristic.
 */
export function estimateTokens(text: string | object | null | undefined): number {
  if (!text) return 0;
  if (typeof text === "string") {
    return Math.ceil(text.length / CHARS_PER_TOKEN);
  }
  const { node, tokens: imageTokens } = extractImageTokens(text, new Set());
  // #7847: count the serialized length instead of building the string. Only `.length` was ever
  // used, and on a multi-megabyte agent body that string is a pure transient allocation.
  // jsonLength is exact (property-tested against JSON.stringify), so the estimate is unchanged.
  return Math.ceil(jsonLength(node) / CHARS_PER_TOKEN) + imageTokens;
}

/**
 * Get token limit for a provider/model combination
 * Priority: Env override > models.dev DB > Registry defaultContextLength > DEFAULT_LIMITS
 */
export function getTokenLimit(provider: string, model: string | null = null): number {
  return resolveTokenLimit(provider, model).limit;
}

/**
 * Resolve a combo target's token limit without crashing when `parseModel(modelStr)`
 * returns `provider: null` (model id with no `provider/` prefix).
 *
 * `ResolvedComboTarget.provider` is populated independently of `modelStr`, so fall
 * back to it before calling `getTokenLimit` (#8716).
 */
export function getComboTargetTokenLimit(options: {
  modelStr?: string | null;
  provider?: string | null;
  parsedProvider?: string | null;
  parsedModel?: string | null;
  targetProvider?: string | null;
}): number {
  let parsedProvider = options.parsedProvider;
  let parsedModel = options.parsedModel;
  if (
    (parsedProvider === undefined || parsedModel === undefined) &&
    Object.prototype.hasOwnProperty.call(options, "modelStr")
  ) {
    const parsed = parseModel(options.modelStr);
    if (parsedProvider === undefined) parsedProvider = parsed.provider;
    if (parsedModel === undefined) parsedModel = parsed.model;
  }
  const provider = parsedProvider ?? options.targetProvider ?? options.provider ?? "unknown";
  return getTokenLimit(provider, parsedModel ?? null);
}

/**
 * Same chain as getTokenLimit, but also reports whether the limit came from
 * a provider/model-specific source (env override, synced DB, registry,
 * name heuristic, curated per-provider default) or only from the generic
 * catch-all default.
 */
function resolveTokenLimit(
  provider: string,
  model: string | null = null
): { limit: number; specific: boolean } {
  // 1. Check environment variable override first
  const envOverride = getEnvOverride(provider);
  if (envOverride) return { limit: envOverride, specific: true };

  const lowerModel = (model || "").toLowerCase();

  // 2. Check models.dev synced DB for per-model context limit
  if (model) {
    const dbLimit = getModelContextLimit(provider, model);
    if (dbLimit && dbLimit > 0) return { limit: dbLimit, specific: true };
  }

  // 3. Check registry for provider default
  const registryEntry = REGISTRY[provider];
  if (registryEntry?.defaultContextLength) {
    return { limit: registryEntry.defaultContextLength, specific: true };
  }

  // 4. Check if model name hints at a known limit
  if (model) {
    if (lowerModel.includes("claude")) return { limit: DEFAULT_LIMITS.claude, specific: true };
    if (lowerModel.includes("gemini")) return { limit: DEFAULT_LIMITS.gemini, specific: true };
    if (
      lowerModel.includes("gpt") ||
      lowerModel.includes("o1") ||
      lowerModel.includes("o3") ||
      lowerModel.includes("o4") ||
      lowerModel.includes("codex")
    )
      return { limit: DEFAULT_LIMITS.codex, specific: true };
  }

  // 5. Fallback to DEFAULT_LIMITS or default
  if (DEFAULT_LIMITS[provider]) return { limit: DEFAULT_LIMITS[provider], specific: true };
  return { limit: DEFAULT_LIMITS.default, specific: false };
}

/**
 * Resolve the context limit to use for proactive compression of a COMBO
 * request.
 *
 * chatCore always executes with the CONCRETE target's provider/model
 * (handleSingleModel resolves the target before delegating), so the
 * executing target's own limit is authoritative. Using min(...allTargets)
 * here — the previous behavior — compressed at the smallest sibling's
 * window even when running on the largest target, destructively purging
 * history long before the real window filled ("agent keeps forgetting").
 *
 * min(...comboTargetLimits) is kept only as a defensive fallback for the
 * case where the current provider/model resolves no specific limit at all.
 */
export function resolveComboContextLimit(options: {
  provider: string;
  model: string | null;
  comboTargetLimits: number[];
}): { limit: number; source: "target" | "combo-min" | "fallback" } {
  const own = resolveTokenLimit(options.provider, options.model ?? null);
  if (own.specific) {
    return { limit: own.limit, source: "target" };
  }
  const knownTargets = (options.comboTargetLimits || []).filter(
    (value) => Number.isFinite(value) && value > 0
  );
  if (knownTargets.length > 0) {
    return { limit: Math.min(...knownTargets), source: "combo-min" };
  }
  return { limit: own.limit, source: "fallback" };
}

/**
 * Apply context compression to request body.
 * Operates in layers of increasing aggressiveness:
 *
 * Layer 1: Trim tool_result messages (truncate long outputs)
 * Layer 1.5: Prune older inline images (keep latest N — #8560)
 * Layer 2: Compress structured thinking blocks (remove from history, keep last)
 * Layer 3: Aggressive purification (drop old messages until fitting)
 *
 * Callers with OpenAI Responses `input[]` (Codex) must adapt via
 * `adaptBodyForCompression` before calling and `restore()` after — this helper
 * is message-centric by design.
 *
 * @param {object} body - Request body with messages[]
 * @param {object} options - { provider?, model?, maxTokens?, reserveTokens?, keepLatestImages? }
 * @returns {{ body: object, compressed: boolean, stats: object }}
 */
export function compressContext(
  body: Record<string, unknown> | null | undefined,
  options: {
    provider?: string;
    model?: string;
    maxTokens?: number;
    reserveTokens?: number;
    keepLatestImages?: number;
  } = {}
) {
  if (!body || !body.messages || !Array.isArray(body.messages)) {
    return { body, compressed: false, stats: {} };
  }

  const provider = options.provider || "default";
  const maxTokens =
    options.maxTokens || getTokenLimit(provider, (body.model as string) || options.model || null);
  const defaultReserveTokens = Math.min(16000, Math.max(256, Math.floor(maxTokens * 0.15)));
  const reserveTokens = Math.min(
    options.reserveTokens ?? getReserveTokensOverride() ?? defaultReserveTokens,
    Math.max(0, maxTokens - 1)
  );
  const targetTokens = Math.max(0, maxTokens - reserveTokens);

  let messages = [...(body.messages as Record<string, unknown>[])];
  // #8594: pass the structured messages array directly — estimateTokens walks it for
  // inline base64 image blocks (#8368) and substitutes a bounded per-image estimate.
  // JSON.stringify()-ing first forces the char/4 text path and mis-measures a ~500KB
  // image as ~125k tokens, triggering needless compression / context loss.
  let currentTokens = estimateTokens(messages);
  const stats = { original: currentTokens, layers: [] as { name: string; tokens: number }[] };

  // Already fits
  if (currentTokens <= targetTokens) {
    return { body, compressed: false, stats: { original: currentTokens, final: currentTokens } };
  }

  // Layer 1: Trim tool_result/tool messages
  messages = trimToolMessages(messages, 2000); // Max 2000 chars per tool result
  currentTokens = estimateTokens(messages); // #8594: object-path keeps the #8368 image estimate
  stats.layers.push({ name: "trim_tools", tokens: currentTokens });

  if (currentTokens <= targetTokens) {
    return {
      body: { ...body, messages },
      compressed: true,
      stats: { ...stats, final: currentTokens },
    };
  }

  // Layer 1.5: Drop oldest inline images while keeping the newest ones (#8560).
  const imagePrune = pruneOlderInlineImages(messages, {
    keepLatest: options.keepLatestImages,
    targetTokens,
  });
  if (imagePrune.pruned > 0) {
    messages = imagePrune.messages;
    currentTokens = estimateTokens(messages);
    stats.layers.push({ name: "prune_images", tokens: currentTokens });
    if (currentTokens <= targetTokens) {
      return {
        body: { ...body, messages },
        compressed: true,
        stats: { ...stats, final: currentTokens },
      };
    }
  }

  // Layer 2: Compress structured thinking blocks (remove from non-last assistant messages)
  messages = compressThinking(messages);
  currentTokens = estimateTokens(messages); // #8594: object-path keeps the #8368 image estimate
  stats.layers.push({ name: "compress_thinking", tokens: currentTokens });

  if (currentTokens <= targetTokens) {
    return {
      body: { ...body, messages },
      compressed: true,
      stats: { ...stats, final: currentTokens },
    };
  }

  // Layer 3: Aggressive purification — drop oldest messages keeping system + last N pairs
  messages = purifyHistory(messages, targetTokens);
  currentTokens = estimateTokens(messages); // #8594: object-path keeps the #8368 image estimate
  stats.layers.push({ name: "purify_history", tokens: currentTokens });

  return {
    body: { ...body, messages },
    compressed: true,
    stats: { ...stats, final: currentTokens },
  };
}

// ─── Layer 1: Trim Tool Messages ────────────────────────────────────────────

function trimToolMessages(messages: Record<string, unknown>[], maxChars: number) {
  return messages.map((msg) => {
    if (msg.role === "tool" && typeof msg.content === "string" && msg.content.length > maxChars) {
      return {
        ...msg,
        content: msg.content.slice(0, maxChars) + "\n... [truncated]",
      };
    }
    // Handle array content (Claude format with tool_result blocks)
    if (msg.role === "user" && Array.isArray(msg.content)) {
      return {
        ...msg,
        content: msg.content.map((block) => {
          if (
            block.type === "tool_result" &&
            typeof block.content === "string" &&
            block.content.length > maxChars
          ) {
            return { ...block, content: block.content.slice(0, maxChars) + "\n... [truncated]" };
          }
          return block;
        }),
      };
    }
    return msg;
  });
}

// ─── Layer 2: Compress Structured Thinking Blocks ───────────────────────────

function compressThinking(messages: Record<string, unknown>[]) {
  // Find last assistant message index
  let lastAssistantIdx = -1;
  for (let i = messages.length - 1; i >= 0; i--) {
    if (messages[i].role === "assistant") {
      lastAssistantIdx = i;
      break;
    }
  }

  return messages.map((msg, i) => {
    if (msg.role !== "assistant") return msg;
    if (i === lastAssistantIdx) return msg; // Keep thinking in last assistant msg

    // Remove thinking blocks from content array
    if (Array.isArray(msg.content)) {
      const filtered = msg.content.filter((block) => block.type !== "thinking");
      if (filtered.length === 0) {
        return { ...msg, content: "[thinking compressed]" };
      }
      return { ...msg, content: filtered };
    }

    return msg;
  });
}

// ─── Layer 3: Aggressive Purification ───────────────────────────────────────

function purifyHistory(messages: Record<string, unknown>[], targetTokens: number) {
  // Keep system message(s) and the last N message pairs
  const system = messages.filter((m) => m.role === "system" || m.role === "developer");
  const nonSystem = messages.filter((m) => m.role !== "system" && m.role !== "developer");

  // Binary search for how many messages to keep from the end
  let keep = nonSystem.length;
  while (keep > 2) {
    let candidate = [...system, ...nonSystem.slice(-keep)];
    candidate = fixToolPairs(candidate);
    candidate = fixToolAdjacency(candidate);
    // Re-run pair fix: fixToolAdjacency may have stripped tool_use blocks, leaving
    // orphan tool_results that Claude rejects ("tool_result without preceding tool_use").
    candidate = fixToolPairs(candidate);
    candidate = stripTrailingAssistantOrphanToolUse(candidate);
    // #8594: measure the candidate structure directly so image-bearing turns are not
    // over-counted and pruned during the binary search.
    const tokens = estimateTokens(candidate);
    if (tokens <= targetTokens) break;
    keep = Math.max(2, Math.floor(keep * 0.7)); // Drop 30% each iteration
  }

  let result = [...system, ...nonSystem.slice(-keep)];
  result = fixToolPairs(result);
  result = fixToolAdjacency(result);
  // Re-run pair fix to drop any tool_result whose matching tool_use was removed by
  // fixToolAdjacency (discussion #2410 — orphan tool_result -> upstream 400).
  result = fixToolPairs(result);
  result = stripTrailingAssistantOrphanToolUse(result);

  // Add summary of dropped messages
  if (keep < nonSystem.length) {
    const dropped = nonSystem.length - keep;
    result.splice(system.length, 0, {
      role: "system",
      content: `[Context compressed: ${dropped} earlier messages removed to fit context window]`,
    });
  }

  return result;
}

/**
 * Remove orphaned tool_result messages whose preceding tool_use was dropped.
 * Also removes orphaned tool_use messages without a corresponding tool_result.
 *
 * When purifyHistory() drops oldest messages, it can split tool_use/tool_result
 * pairs — keeping the tool_result but dropping the tool_use that initiated it.
 * This causes upstream providers to reject the request with errors like:
 *   - Claude: "tool_result message must be preceded by a tool_use message"
 *   - OpenAI: "Invalid message format"
 *   - Gemini: "Function response without function call"
 */
export function fixToolPairs(messages: Record<string, unknown>[]) {
  // Pass 1: Collect all tool_result IDs from user/tool messages
  const toolResultIds = new Set();
  for (const msg of messages) {
    if (msg.role === "tool" && msg.tool_call_id) {
      toolResultIds.add(msg.tool_call_id);
    }
    if (msg.role === "user" && Array.isArray(msg.content)) {
      for (const block of msg.content) {
        if (block.type === "tool_result" && block.tool_use_id) {
          toolResultIds.add(block.tool_use_id);
        }
      }
    }
  }

  // Pass 2: Filter assistant messages to remove tool_use without tool_result
  // (Exception: keep tool_use if the assistant message is the last message)
  const isLastMessage = (idx: number) => idx === messages.length - 1;
  const filteredMessages = messages.map((msg, idx) => {
    if (msg.role === "assistant" && !isLastMessage(idx)) {
      let modified = false;
      const newMsg = { ...msg };

      if (Array.isArray(newMsg.tool_calls)) {
        const filteredToolCalls = newMsg.tool_calls.filter(
          (tc: Record<string, unknown>) => !tc.id || toolResultIds.has(tc.id)
        );
        if (filteredToolCalls.length !== newMsg.tool_calls.length) {
          newMsg.tool_calls = filteredToolCalls;
          modified = true;
        }
      }

      if (Array.isArray(newMsg.content)) {
        const filteredContent = newMsg.content.filter(
          (block: Record<string, unknown>) =>
            block.type !== "tool_use" || !block.id || toolResultIds.has(block.id)
        );
        if (filteredContent.length !== newMsg.content.length) {
          newMsg.content = filteredContent;
          modified = true;
        }
      }

      return modified ? newMsg : msg;
    }
    return msg;
  });

  // Pass 3: Collect all remaining tool_use IDs from assistant messages
  const toolCallIds = new Set();
  for (const msg of filteredMessages) {
    if (msg.role === "assistant") {
      if (Array.isArray(msg.tool_calls)) {
        for (const tc of msg.tool_calls) {
          if (tc.id) toolCallIds.add(tc.id);
        }
      }
      if (Array.isArray(msg.content)) {
        for (const block of msg.content) {
          if (block.type === "tool_use" && block.id) {
            toolCallIds.add(block.id);
          }
        }
      }
    }
  }

  // Pass 4: Filter user/tool messages to remove tool_result without tool_use
  return filteredMessages
    .map((msg) => {
      if (msg.role === "tool" && msg.tool_call_id) {
        if (!toolCallIds.has(msg.tool_call_id)) return null;
      }

      if (msg.role === "user" && Array.isArray(msg.content)) {
        const filteredContent = msg.content.filter(
          (block: Record<string, unknown>) =>
            block.type !== "tool_result" || !block.tool_use_id || toolCallIds.has(block.tool_use_id)
        );
        if (filteredContent.length !== msg.content.length) {
          if (filteredContent.length === 0) return null;
          return { ...msg, content: filteredContent };
        }
      }

      // Drop assistant messages if their content AND tool_calls became empty
      if (msg.role === "assistant") {
        const hasContent =
          typeof msg.content === "string"
            ? msg.content.trim().length > 0
            : Array.isArray(msg.content) && msg.content.length > 0;
        const hasToolCalls = Array.isArray(msg.tool_calls) && msg.tool_calls.length > 0;
        if (!hasContent && !hasToolCalls) {
          return null;
        }
      }

      return msg;
    })
    .filter(Boolean) as Record<string, unknown>[];
}

/**
 * Adjacency guard: Claude requires `tool_result` in the IMMEDIATELY NEXT
 * message after `tool_use`, not just somewhere later in the array.
 *
 * `fixToolPairs` checks global ID presence but not adjacency. This function
 * runs after `fixToolPairs` and removes `tool_use` blocks from assistant
 * messages where the next message does not contain a matching `tool_result`.
 */
export function fixToolAdjacency(messages: Record<string, unknown>[]): Record<string, unknown>[] {
  if (messages.length <= 1) return messages;

  const result: Record<string, unknown>[] = [];

  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    const nextMsg = messages[i + 1];

    if (msg.role !== "assistant" || !nextMsg) {
      result.push(msg);
      continue;
    }

    // Collect tool_result IDs from the NEXT message only
    const nextToolResultIds = new Set<string>();
    if (nextMsg.role === "tool" && nextMsg.tool_call_id) {
      nextToolResultIds.add(String(nextMsg.tool_call_id));
    }
    if (nextMsg.role === "user" && Array.isArray(nextMsg.content)) {
      for (const block of nextMsg.content as Record<string, unknown>[]) {
        if (block.type === "tool_result" && block.tool_use_id) {
          nextToolResultIds.add(String(block.tool_use_id));
        }
      }
    }

    let modified = false;
    const newMsg: Record<string, unknown> = { ...msg };

    // Filter tool_use blocks in content array (Claude format)
    if (Array.isArray(newMsg.content)) {
      const filteredContent = (newMsg.content as Record<string, unknown>[]).filter(
        (block) => block.type !== "tool_use" || !block.id || nextToolResultIds.has(String(block.id))
      );
      if (filteredContent.length !== (newMsg.content as unknown[]).length) {
        newMsg.content = filteredContent;
        modified = true;
      }
    }

    // Filter tool_calls array (OpenAI format) — independently of content
    if (Array.isArray(newMsg.tool_calls)) {
      const filteredToolCalls = (newMsg.tool_calls as Record<string, unknown>[]).filter(
        (tc: Record<string, unknown>) => !tc.id || nextToolResultIds.has(String(tc.id))
      );
      if (filteredToolCalls.length !== (newMsg.tool_calls as unknown[]).length) {
        newMsg.tool_calls = filteredToolCalls;
        modified = true;
      }
    }

    if (modified) {
      // Drop assistant message if it became empty
      const hasContent =
        typeof newMsg.content === "string"
          ? (newMsg.content as string).trim().length > 0
          : Array.isArray(newMsg.content) && (newMsg.content as unknown[]).length > 0;
      const hasToolCalls = Array.isArray(newMsg.tool_calls) && newMsg.tool_calls.length > 0;
      if (!hasContent && !hasToolCalls) continue;
      result.push(newMsg);
    } else {
      result.push(msg);
    }
  }

  return result;
}

/**
 * Upstream-send guard: after `fixToolPairs`, strip a trailing assistant
 * message whose only/remaining content is an orphan `tool_use` block.
 *
 * `fixToolPairs` intentionally preserves a final-message `tool_use` because
 * during context pruning the client is still waiting on the matching
 * `tool_result` — dropping it there would lose state. But on the
 * upstream-send path the request body must end on a user turn; a trailing
 * `assistant(tool_use)` triggers the same Anthropic 400 the guard is
 * trying to prevent:
 *   messages.N: `tool_use` ids were found without `tool_result` blocks
 *   immediately after: toolu_...
 *
 * Behavior:
 *  - If the last message is `assistant` and contains any `tool_use` block,
 *    those blocks are removed.
 *  - If removal leaves the message with no content / tool_calls at all, the
 *    message itself is dropped.
 *  - Idempotent on clean histories (trailing user, trailing assistant with
 *    only text/thinking, etc.).
 */
export function stripTrailingAssistantOrphanToolUse(
  messages: Record<string, unknown>[]
): Record<string, unknown>[] {
  if (!Array.isArray(messages) || messages.length === 0) return messages;

  const lastIdx = messages.length - 1;
  const last = messages[lastIdx];
  if (!last || last.role !== "assistant") return messages;

  let modified = false;
  const newLast: Record<string, unknown> = { ...last };

  if (Array.isArray(newLast.tool_calls)) {
    const filteredCalls = (newLast.tool_calls as Record<string, unknown>[]).filter(
      () => false // remove all trailing tool_calls (none can be paired by definition)
    );
    if (filteredCalls.length !== (newLast.tool_calls as unknown[]).length) {
      newLast.tool_calls = filteredCalls;
      modified = true;
    }
  }

  if (Array.isArray(newLast.content)) {
    const filteredContent = (newLast.content as Record<string, unknown>[]).filter(
      (block) => block.type !== "tool_use"
    );
    if (filteredContent.length !== (newLast.content as unknown[]).length) {
      newLast.content = filteredContent;
      modified = true;
    }
  }

  if (!modified) return messages;

  // If the last message is now empty, drop it.
  const hasContent =
    typeof newLast.content === "string"
      ? (newLast.content as string).trim().length > 0
      : Array.isArray(newLast.content) && (newLast.content as unknown[]).length > 0;
  const hasToolCalls =
    Array.isArray(newLast.tool_calls) && (newLast.tool_calls as unknown[]).length > 0;

  const result = messages.slice(0, lastIdx);
  if (hasContent || hasToolCalls) result.push(newLast);
  return result;
}

/**
 * Providers that strictly require the last message to be `user` or `tool`.
 * A trailing `assistant` message with plain text content (no tool_use) is
 * valid for Anthropic/OpenAI (signals "continue from here") but rejected by
 * Mistral with: "Expected last role User or Tool … but got assistant" (#3396).
 */
const PROVIDERS_REQUIRING_USER_LAST_MESSAGE = new Set(["mistral"]);

/**
 * Strip a trailing `assistant` message that contains ONLY plain text (no
 * `tool_use` / `tool_calls`) for providers that mandate user-last format.
 *
 * Call this AFTER `stripTrailingAssistantOrphanToolUse` on the upstream-send
 * path so `tool_use` orphans are already removed before this check runs.
 */
export function stripTrailingAssistantForProvider(
  messages: Record<string, unknown>[],
  provider: string
): Record<string, unknown>[] {
  if (!PROVIDERS_REQUIRING_USER_LAST_MESSAGE.has(provider)) return messages;
  if (!Array.isArray(messages) || messages.length === 0) return messages;

  const last = messages[messages.length - 1];
  if (!last || last.role !== "assistant") return messages;

  // Only strip when the message has NO tool_use / tool_calls (those are
  // handled by stripTrailingAssistantOrphanToolUse upstream of this call).
  const hasToolUse =
    Array.isArray(last.content) &&
    (last.content as Record<string, unknown>[]).some((b) => b.type === "tool_use");
  const hasToolCalls = Array.isArray(last.tool_calls) && (last.tool_calls as unknown[]).length > 0;
  if (hasToolUse || hasToolCalls) return messages;

  return messages.slice(0, messages.length - 1);
}

/**
 * Serialized JSON length without materializing the JSON (#7847).
 *
 * Several hot-path call sites only need `JSON.stringify(body).length` — a readiness-timeout
 * threshold, a payload-size metric, a token estimate. On a 3.05 MiB agent request each of those
 * allocates a full 3 MiB string that is read once for its length and thrown away, and #7847
 * reports that class of transient allocation driving V8/cgroup OOM under concurrent long-context
 * traffic.
 *
 * `jsonLength()` walks the value and counts instead. Same O(n) scan, no allocation.
 *
 * It is EXACT, not an approximation: every consumer feeds a threshold, and an approximation
 * would silently shift routing and timeout decisions. `tests/unit/json-size-exactness.test.ts`
 * property-tests `jsonLength(x) === JSON.stringify(x).length` over generated structures.
 *
 * Anything outside the plain-JSON subset (Date, toJSON, class instances, Map, ...) falls back to
 * `JSON.stringify` for THAT SUBTREE only, so an exotic leaf never forces the multi-megabyte
 * message history back onto the allocating path.
 */

/** Length of a JSON-encoded string, including the surrounding quotes. */
function encodedStringLength(value: string): number {
  let len = 2; // the quotes
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code === 0x22 || code === 0x5c) {
      len += 2; // \" and \\
    } else if (code === 0x08 || code === 0x09 || code === 0x0a || code === 0x0c || code === 0x0d) {
      len += 2; // \b \t \n \f \r
    } else if (code < 0x20) {
      len += 6; // \u00XX
    } else if (code >= 0xd800 && code <= 0xdfff) {
      // Surrogates: a well-formed pair serializes as its two code units (2 chars); a LONE
      // surrogate is escaped as \uXXXX since ES2019 well-formed JSON.stringify.
      const isHigh = code <= 0xdbff;
      const next = isHigh ? value.charCodeAt(i + 1) : NaN;
      const paired = isHigh && next >= 0xdc00 && next <= 0xdfff;
      if (paired) {
        len += 2;
        i++; // consume the low surrogate
      } else {
        len += 6;
      }
    } else {
      len += 1;
    }
  }
  return len;
}

/** True for values JSON.stringify drops (object values) or renders as null (array items). */
function isOmitted(value: unknown): boolean {
  return value === undefined || typeof value === "function" || typeof value === "symbol";
}

function isPlainContainer(value: object): boolean {
  if (Array.isArray(value)) return true;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

/**
 * Exact `JSON.stringify(value).length`, computed without building the string.
 * Returns 0 for values JSON.stringify renders as `undefined` (functions, symbols, undefined),
 * matching the `try { JSON.stringify(x).length } catch { 0 }` shape of the call sites replaced.
 * Throws on circular structures and BigInt, exactly as JSON.stringify does.
 */
export function jsonLength(value: unknown): number {
  return lengthOf(value, new Set<object>());
}

function lengthOf(value: unknown, seen: Set<object>): number {
  if (value === null) return 4; // "null"
  const type = typeof value;

  if (type === "string") return encodedStringLength(value as string);
  if (type === "boolean") return value ? 4 : 5;
  if (type === "number") {
    // Non-finite numbers serialize as null.
    return Number.isFinite(value as number) ? String(value).length : 4;
  }
  if (type === "bigint") {
    // Match JSON.stringify, which throws rather than guessing an encoding.
    throw new TypeError("Do not know how to serialize a BigInt");
  }
  if (isOmitted(value)) return 0;
  if (type !== "object") return 0;

  const obj = value as object;

  // Delegate anything that is not a plain object/array — Date, class instances with toJSON,
  // Map, boxed primitives. Scoped to this subtree so the big arrays stay on the fast path.
  if (!isPlainContainer(obj) || typeof (obj as { toJSON?: unknown }).toJSON === "function") {
    const encoded = JSON.stringify(obj);
    return encoded === undefined ? 0 : encoded.length;
  }

  if (seen.has(obj)) {
    throw new TypeError("Converting circular structure to JSON");
  }
  seen.add(obj);
  try {
    if (Array.isArray(obj)) {
      let len = 2; // []
      for (let i = 0; i < obj.length; i++) {
        if (i > 0) len += 1; // comma
        const item = obj[i];
        // Omitted values render as null inside arrays rather than disappearing.
        len += isOmitted(item) ? 4 : lengthOf(item, seen);
      }
      return len;
    }

    let len = 2; // {}
    let first = true;
    for (const key of Object.keys(obj)) {
      const item = (obj as Record<string, unknown>)[key];
      if (isOmitted(item)) continue; // the whole entry disappears
      if (!first) len += 1; // comma
      first = false;
      len += encodedStringLength(key) + 1 + lengthOf(item, seen); // "key":value
    }
    return len;
  } finally {
    seen.delete(obj);
  }
}

// Gemini helper functions for translator

import { safeParseJSON } from "./jsonUtil.ts";

type JsonRecord = Record<string, unknown>;

// Unsupported JSON Schema constraints that should be removed for Antigravity.
// `additionalProperties` is handled separately so `true` can be preserved.
export const GEMINI_UNSUPPORTED_SCHEMA_KEYS = new Set([
  // Basic constraints (not supported by Gemini API)
  "minLength",
  "maxLength",
  "exclusiveMinimum",
  "exclusiveMaximum",
  // `multipleOf` is not part of the Gemini/antigravity OpenAPI 3.0 schema subset;
  // leaving it in function_declarations triggers a hard upstream 400
  // ("Unknown name \"multipleOf\""). `minimum`/`maximum` ARE accepted and kept.
  "multipleOf",
  // OpenAI "strict" tool-calling mode embeds `strict: true/false` directly inside
  // a function's `parameters` schema (RubyLLM and other OpenAI-convention clients
  // do this by default). Gemini's function_declarations schema doesn't recognize
  // it and 400s the same way ("Unknown name \"strict\" ... Cannot find field").
  "strict",
  // NOTE: `pattern` is intentionally NOT in this set. Antigravity (Gemini-derived
  // surface) accepts `pattern` on string constraints, and glob/grep/file-search
  // tools depend on it to express their argument regex. Removing it produced
  // upstream 400s and wrong-tool semantics (decolua/9router#1368).
  "minItems",
  "maxItems",
  "format",
  // Claude rejects these in VALIDATED mode
  "default",
  "examples",
  // JSON Schema meta keywords
  "$schema",
  "$id",
  "$anchor",
  "$dynamicRef",
  "$dynamicAnchor",
  "$vocabulary",
  "$comment",
  "$defs",
  "definitions",
  "const",
  "$ref",
  "ref",
  // Object validation keywords (not supported)
  "propertyNames",
  "patternProperties",
  "unevaluatedProperties",
  "unevaluatedItems",
  "contains",
  "minContains",
  "maxContains",
  // Complex schema keywords (handled by flattenAnyOfOneOf/mergeAllOf)
  "anyOf",
  "oneOf",
  "allOf",
  "not",
  // Dependency keywords (not supported)
  "dependencies",
  "dependentSchemas",
  "dependentRequired",
  // Other unsupported keywords
  "title",
  "if",
  "then",
  "else",
  "contentMediaType",
  "contentEncoding",
  "contentSchema",
  "readOnly",
  "writeOnly",
  // Non-standard schema fields (not recognized by Gemini API)
  "deprecated",
  "optional",
  // VS Code / JSON Language Service extensions injected by GitHub Copilot tools (#1175)
  "enumDescriptions",
  "markdownDescription",
  "markdownEnumDescriptions",
  "enumItemLabels",
  "tags",
  // UI/Styling properties (from Cursor tools - NOT JSON Schema standard)
  "cornerRadius",
  "fillColor",
  "fontFamily",
  "fontSize",
  "fontWeight",
  "gap",
  "padding",
  "strokeColor",
  "strokeThickness",
  "textColor",
]);

export const UNSUPPORTED_SCHEMA_CONSTRAINTS = [...GEMINI_UNSUPPORTED_SCHEMA_KEYS];

// Default safety settings for the standard Gemini API surface.
//
// HARM_CATEGORY_CIVIC_INTEGRITY is intentionally NOT included here (#8231): the
// dynamic validation on some models/endpoints rejects it with a hard 400
// (`safety_settings[N]: element predicate failed`), taking down every request
// through that model. The Antigravity/Cloud Code surface already worked around
// this for #5003 (see ANTIGRAVITY_UNSUPPORTED_SAFETY_CATEGORIES in
// open-sse/executors/antigravity.ts) — this drops the same category from the
// standard-path default so behavior is consistent across Gemini surfaces. A
// caller that explicitly supplies safetySettings (including one that itself
// requests CIVIC_INTEGRITY) is still honored as-is — only this unconditional
// default is scoped down.
export const DEFAULT_SAFETY_SETTINGS = [
  { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "OFF" },
  { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "OFF" },
  { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "OFF" },
  { category: "HARM_CATEGORY_HARASSMENT", threshold: "OFF" },
];

function normalizeAudioMimeType(format: unknown): string {
  const normalized =
    typeof format === "string" && format.trim() ? format.trim().toLowerCase() : "wav";
  if (normalized === "mp3") {
    return "audio/mpeg";
  }
  return `audio/${normalized}`;
}

// Convert OpenAI content to Gemini parts
export function convertOpenAIContentToParts(content: unknown): JsonRecord[] {
  const parts: JsonRecord[] = [];

  if (typeof content === "string") {
    parts.push({ text: content });
  } else if (Array.isArray(content)) {
    for (const item of content) {
      const rec = toRecord(item);
      if (rec.type === "text") {
        parts.push({ text: rec.text });
      } else if (rec.type === "input_audio" || rec.type === "audio") {
        const audio = toRecord(rec.input_audio || rec.audio);
        if (typeof audio.data === "string" && audio.data) {
          parts.push({
            inlineData: {
              mimeType: normalizeAudioMimeType(audio.format),
              data: audio.data.replace(/^data:[a-zA-Z0-9/+-]+;base64,/, ""),
            },
          });
        }
      } else if (rec.type === "audio_url") {
        // OpenAI-style audio_url (data: URI). Mirrors the image_url data-URL
        // parser below but produces an audio inlineData part (#913).
        const audioUrl = toRecord(rec.audio_url);
        const url = typeof audioUrl.url === "string" ? audioUrl.url : "";
        if (url.startsWith("data:")) {
          const commaIndex = url.indexOf(",");
          if (commaIndex !== -1) {
            const mimePart = url.substring(5, commaIndex); // skip "data:"
            const data = url.substring(commaIndex + 1);
            const mimeType = mimePart.split(";")[0] || "audio/wav";
            parts.push({ inlineData: { mimeType, data } });
          }
        }
      } else {
        // 1. Handle Gemini native inline_data injected into OpenAI arrays (e.g. Cherry Studio)
        const geminiInline = toRecord(rec.inline_data || rec.inlineData);
        if (geminiInline?.data) {
          parts.push({
            inlineData: {
              mimeType: String(
                geminiInline.mime_type || geminiInline.mimeType || "application/pdf"
              ),
              data: String(geminiInline.data).replace(/^data:[a-zA-Z0-9/+-]+;base64,/, ""),
            },
          });
          continue;
        }

        // 2. Handle Claude-style source blocks commonly used by AI clients
        const source = toRecord(rec.source);
        if (source?.type === "base64" && source?.data) {
          parts.push({
            inlineData: {
              mimeType: String(source.media_type || "application/pdf"),
              data: String(source.data).replace(/^data:[a-zA-Z0-9/+-]+;base64,/, ""),
            },
          });
          continue;
        }

        // 3. Handle raw data strings (e.g. {"type": "file", "data": "JVBER...", "mime_type": "..."}).
        //    Also accept the Responses-API shape {"type":"input_file","file_data":"JVBER...","filename":...}
        //    AND the OpenAI Chat Completions shape
        //    {"type":"file","file":{"filename":...,"file_data":"data:<mime>;base64,..."}} so PDFs and
        //    videos reach Gemini instead of being silently dropped (#2515). Gemini reads
        //    application/pdf and video/* natively via inlineData, exactly like images.
        const file = toRecord(rec.file);
        const doc = toRecord(rec.document);
        const rawDataStr =
          rec.data || rec.file_data || file?.data || file?.file_data || doc?.data || doc?.file_data;
        if (typeof rawDataStr === "string" && !rawDataStr.startsWith("http")) {
          // Prefer the mime embedded in the data: URI (e.g. application/pdf, video/mp4) so
          // documents and videos are not mislabeled as the fallback; the fallback applies
          // only to bare base64 that carries no data: prefix.
          let mimeType =
            rec.mime_type ||
            rec.media_type ||
            file?.mime_type ||
            doc?.mime_type ||
            "application/pdf";
          if (rawDataStr.startsWith("data:")) {
            const commaIndex = rawDataStr.indexOf(",");
            if (commaIndex !== -1) {
              const parsedMime = rawDataStr.substring(5, commaIndex).split(";")[0];
              if (parsedMime) mimeType = parsedMime;
            }
          }
          const rawData = rawDataStr.replace(/^data:[a-zA-Z0-9/+-]+;base64,/, "");
          parts.push({
            inlineData: {
              mimeType: String(mimeType),
              data: rawData,
            },
          });
          continue;
        }

        // 4. Standard OpenAI Data URIs
        const imageUrl = toRecord(rec.image_url);
        const imageObj = toRecord(rec.image);
        const fileUrl = toRecord(rec.file_url);
        const fileObj = toRecord(rec.file);
        const docObj = toRecord(rec.document);
        // `file_url` is a top-level string on the Responses-API input_file shape (#2515).
        // `rec.image` (with nested {url}) is emitted by some MCP tool wrappers and
        // translation layers as an alternative to `rec.image_url` (#2807).
        const fileData =
          (typeof rec.file_url === "string" ? rec.file_url : undefined) ||
          // AI SDK-style image part: { type: "image", image: "data:...;base64,..." } (#1330)
          (typeof rec.image === "string" ? rec.image : undefined) ||
          imageUrl?.url ||
          imageObj?.url ||
          fileUrl?.url ||
          fileObj?.url ||
          docObj?.url;
        if (typeof fileData === "string" && fileData.startsWith("data:")) {
          const commaIndex = fileData.indexOf(",");
          if (commaIndex !== -1) {
            const mimePart = fileData.substring(5, commaIndex); // skip "data:"
            const data = fileData.substring(commaIndex + 1);
            const mimeType = mimePart.split(";")[0];

            parts.push({
              inlineData: { mimeType, data },
            });
          }
        } else if (typeof fileData === "string" && /^https?:\/\//i.test(fileData)) {
          // Remote URLs cannot be embedded as inlineData (which requires base64),
          // but Gemini's Part schema natively accepts `fileData: { fileUri }` for
          // HTTP/HTTPS sources — the model fetches the asset itself. Pass the URL
          // through instead of dropping it (#2807; ported from upstream PR #344).
          // The MIME type is intentionally `image/*` because we do not block on
          // a HEAD request to sniff it; Gemini infers the concrete type on fetch.
          parts.push({
            fileData: { fileUri: fileData, mimeType: "image/*" },
          });
        }
      }
    }
  }

  return parts;
}

// Extract text content from OpenAI content
export function extractTextContent(content: unknown): string {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content
      .map((item) => toRecord(item))
      .filter((c) => c.type === "text")
      .map((c) => (typeof c.text === "string" ? c.text : ""))
      .join("");
  }
  return "";
}

// Try parse JSON safely (null fallback on parse error; re-export keeps legacy API).
export function tryParseJSON(str: unknown): unknown {
  return safeParseJSON(str, null);
}

// Generate request ID
export function generateRequestId() {
  return `agent-${crypto.randomUUID()}`;
}

// Generate session ID
export function generateSessionId() {
  const arr = new BigUint64Array(1);
  globalThis.crypto.getRandomValues(arr);
  const num = arr[0] % 9000000000000000000n;
  return `-${num.toString()}`;
}

function cloneSchemaValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => cloneSchemaValue(item));
  }
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([key, nestedValue]) => [key, cloneSchemaValue(nestedValue)])
    );
  }
  return value;
}

function toRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function decodeJsonPointerSegment(segment: unknown): string {
  return String(segment).replace(/~1/g, "/").replace(/~0/g, "~");
}

function resolveLocalReference(root: unknown, ref: unknown): unknown | null {
  if (typeof ref !== "string" || !ref.startsWith("#/")) return null;

  let current: unknown = root;
  const segments = ref
    .slice(2)
    .split("/")
    .filter(Boolean)
    .map((segment) => decodeJsonPointerSegment(segment));

  for (const segment of segments) {
    const currentRecord = toRecord(current);
    if (!(segment in currentRecord)) {
      return null;
    }
    current = currentRecord[segment];
  }

  return current;
}

function inlineLocalSchemaRefs(
  node: unknown,
  root: unknown,
  activeRefs: Set<string> = new Set<string>()
): unknown {
  if (Array.isArray(node)) {
    return node.map((item) => inlineLocalSchemaRefs(item, root, activeRefs));
  }

  if (!node || typeof node !== "object") {
    return node;
  }

  const record: JsonRecord = { ...toRecord(node) };
  const ref = typeof record.$ref === "string" ? record.$ref : "";
  if (ref.startsWith("#/$defs/") || ref.startsWith("#/definitions/")) {
    const rest = { ...record };
    delete rest.$ref;

    if (activeRefs.has(ref)) {
      return inlineLocalSchemaRefs(rest, root, activeRefs);
    }

    const resolved = resolveLocalReference(root, ref);
    if (!resolved || typeof resolved !== "object") {
      return inlineLocalSchemaRefs(rest, root, activeRefs);
    }

    activeRefs.add(ref);
    const merged = {
      ...toRecord(inlineLocalSchemaRefs(cloneSchemaValue(resolved), root, activeRefs)),
      ...rest,
    };
    activeRefs.delete(ref);
    return inlineLocalSchemaRefs(merged, root, activeRefs);
  }

  return Object.fromEntries(
    Object.entries(record).map(([key, value]) => [
      key,
      inlineLocalSchemaRefs(value, root, activeRefs),
    ])
  );
}

// Helper: Remove unsupported keywords recursively from object/array
function removeUnsupportedKeywords(obj: unknown, keywords: Set<string>): void {
  if (!obj || typeof obj !== "object") return;

  if (Array.isArray(obj)) {
    for (const item of obj) {
      removeUnsupportedKeywords(item, keywords);
    }
    return;
  }

  const record = obj as JsonRecord;
  // Delete unsupported *constraint* keywords at the current schema level.
  for (const key of Object.keys(record)) {
    if (keywords.has(key) || key.startsWith("x-")) {
      delete record[key];
    }
  }
  // Recurse into remaining values. `properties` is a map keyed by arbitrary,
  // user-defined property NAMES — a tool may legitimately declare a property
  // called `pattern`, `enum`, `minLength`, etc. Descend into each property's
  // subschema, but never run keyword-deletion against the property names
  // themselves, or glob/grep-style tools lose their `pattern` argument (#1368).
  for (const [key, value] of Object.entries(record)) {
    if (!value || typeof value !== "object") continue;
    if (key === "properties" && !Array.isArray(value)) {
      for (const subSchema of Object.values(value as JsonRecord)) {
        removeUnsupportedKeywords(subSchema, keywords);
      }
    } else {
      removeUnsupportedKeywords(value, keywords);
    }
  }
}

function normalizeAdditionalProperties(obj: unknown): void {
  if (!obj || typeof obj !== "object") return;

  if (Array.isArray(obj)) {
    for (const item of obj) {
      normalizeAdditionalProperties(item);
    }
    return;
  }

  const record = obj as JsonRecord;

  // Gemini API does not support `additionalProperties` at all in function_declarations
  // schemas (returns 400 "Unknown name"). Since Gemini defaults to allowing additional
  // properties anyway, stripping it unconditionally is safe and prevents errors (#1421).
  if ("additionalProperties" in record) {
    delete record.additionalProperties;
  }

  for (const value of Object.values(record)) {
    if (value && typeof value === "object") {
      normalizeAdditionalProperties(value);
    }
  }
}

// Convert const to enum
function convertConstToEnum(obj: unknown): void {
  if (!obj || typeof obj !== "object") return;

  const record = obj as JsonRecord;
  if (record.const !== undefined && !record.enum) {
    record.enum = [record.const];
    delete record.const;
  }

  for (const value of Object.values(record)) {
    if (value && typeof value === "object") {
      convertConstToEnum(value);
    }
  }
}

// Convert enum values to strings (Gemini requires string enum values)
// For integer types, remove enum entirely as Gemini doesn't support it
function convertEnumValuesToStrings(obj: unknown): void {
  if (!obj || typeof obj !== "object") return;

  const record = obj as JsonRecord;
  if (record.enum && Array.isArray(record.enum)) {
    // Gemini only supports enum for string types, not integer
    if (record.type === "integer" || record.type === "number") {
      delete record.enum;
    } else {
      record.enum = record.enum.map((v: unknown) => String(v));
      if (!record.type) {
        record.type = "string";
      }
    }
  }

  for (const value of Object.values(record)) {
    if (value && typeof value === "object") {
      convertEnumValuesToStrings(value);
    }
  }
}

// Merge allOf schemas
function mergeAllOf(obj: unknown): void {
  if (!obj || typeof obj !== "object") return;

  const record = obj as JsonRecord;
  if (record.allOf && Array.isArray(record.allOf)) {
    const merged: { properties?: JsonRecord; required?: string[] } = {};

    for (const item of record.allOf) {
      const itemRecord = toRecord(item);
      const itemProperties = toRecord(itemRecord.properties);
      if (Object.keys(itemProperties).length > 0) {
        if (!merged.properties) merged.properties = {};
        Object.assign(merged.properties, itemProperties);
      }
      if (itemRecord.required && Array.isArray(itemRecord.required)) {
        if (!merged.required) merged.required = [];
        for (const req of itemRecord.required) {
          if (typeof req === "string" && !merged.required.includes(req)) {
            merged.required.push(req);
          }
        }
      }
    }

    delete record.allOf;
    if (merged.properties)
      record.properties = { ...toRecord(record.properties), ...merged.properties };
    if (merged.required) {
      const required = Array.isArray(record.required)
        ? record.required.filter((item): item is string => typeof item === "string")
        : [];
      record.required = [...required, ...merged.required];
    }
  }

  for (const value of Object.values(record)) {
    if (value && typeof value === "object") {
      mergeAllOf(value);
    }
  }
}

// Select best schema from anyOf/oneOf
function selectBest(items: unknown[]): number {
  let bestIdx = 0;
  let bestScore = -1;

  for (let i = 0; i < items.length; i++) {
    const item = toRecord(items[i]);
    let score = 0;
    const type = item.type;

    if (type === "object" || item.properties) {
      score = 3;
    } else if (type === "array" || item.items) {
      score = 2;
    } else if (type && type !== "null") {
      score = 1;
    }

    if (score > bestScore) {
      bestScore = score;
      bestIdx = i;
    }
  }

  return bestIdx;
}

// Flatten anyOf/oneOf
function flattenAnyOfOneOf(obj: unknown): void {
  if (!obj || typeof obj !== "object") return;

  const record = obj as JsonRecord;
  if (record.anyOf && Array.isArray(record.anyOf) && record.anyOf.length > 0) {
    const nonNullSchemas = record.anyOf.filter((s) => s && toRecord(s).type !== "null");
    if (nonNullSchemas.length > 0) {
      const bestIdx = selectBest(nonNullSchemas);
      const selected = nonNullSchemas[bestIdx];
      delete record.anyOf;
      Object.assign(record, toRecord(selected));
    }
  }

  if (record.oneOf && Array.isArray(record.oneOf) && record.oneOf.length > 0) {
    const nonNullSchemas = record.oneOf.filter((s) => s && toRecord(s).type !== "null");
    if (nonNullSchemas.length > 0) {
      const bestIdx = selectBest(nonNullSchemas);
      const selected = nonNullSchemas[bestIdx];
      delete record.oneOf;
      Object.assign(record, toRecord(selected));
    }
  }

  for (const value of Object.values(record)) {
    if (value && typeof value === "object") {
      flattenAnyOfOneOf(value);
    }
  }
}

// Flatten type arrays
function flattenTypeArrays(obj: unknown): void {
  if (!obj || typeof obj !== "object") return;

  const record = obj as JsonRecord;
  if (record.type && Array.isArray(record.type)) {
    const nonNullTypes = record.type.filter((t) => t !== "null");
    record.type = nonNullTypes.length > 0 ? nonNullTypes[0] : "string";
  }

  for (const value of Object.values(record)) {
    if (value && typeof value === "object") {
      flattenTypeArrays(value);
    }
  }
}

// Clean JSON Schema for Antigravity API compatibility - removes unsupported keywords recursively
// Reference: CLIProxyAPI/internal/util/gemini_schema.go
export function cleanJSONSchemaForAntigravity(schema: unknown): unknown {
  if (!schema || typeof schema !== "object") return schema;

  const root = cloneSchemaValue(schema);
  let cleaned = inlineLocalSchemaRefs(root, root);

  // Phase 1: Convert and prepare
  convertConstToEnum(cleaned);
  convertEnumValuesToStrings(cleaned);

  // Phase 2: Flatten complex structures
  mergeAllOf(cleaned);
  flattenAnyOfOneOf(cleaned);
  flattenTypeArrays(cleaned);

  // Phase 3: Preserve the only supported additionalProperties shape before keyword cleanup.
  normalizeAdditionalProperties(cleaned);

  // Phase 4: Remove all unsupported keywords at ALL levels (including inside arrays).
  removeUnsupportedKeywords(cleaned, GEMINI_UNSUPPORTED_SCHEMA_KEYS);

  // Phase 5: Cleanup required fields recursively.
  function cleanupRequired(obj: unknown): void {
    if (!obj || typeof obj !== "object") return;

    const record = obj as JsonRecord;
    if (record.required && Array.isArray(record.required) && record.properties) {
      const properties = toRecord(record.properties);
      const validRequired = record.required.filter(
        (field) =>
          typeof field === "string" && Object.prototype.hasOwnProperty.call(properties, field)
      );
      if (validRequired.length === 0) {
        delete record.required;
      } else {
        record.required = validRequired;
      }
    }

    // Recurse into nested objects
    for (const value of Object.values(record)) {
      if (value && typeof value === "object") {
        cleanupRequired(value);
      }
    }
  }

  cleanupRequired(cleaned);

  // Phase 6: Add placeholder for empty object schemas (Antigravity requirement).
  function addPlaceholders(obj: unknown): void {
    if (!obj || typeof obj !== "object") return;

    const record = obj as JsonRecord;
    if (record.type === "object") {
      if (!record.properties || Object.keys(toRecord(record.properties)).length === 0) {
        record.properties = {
          reason: {
            type: "string",
            description: "Brief explanation of why you are calling this tool",
          },
        };
        record.required = ["reason"];
      }
    }

    // Recurse into nested objects
    for (const value of Object.values(record)) {
      if (value && typeof value === "object") {
        addPlaceholders(value);
      }
    }
  }

  addPlaceholders(cleaned);

  return cleaned;
}

import { createHash } from "crypto";

import { cleanJSONSchemaForAntigravity } from "./geminiHelper.ts";

type GeminiFunctionDeclaration = {
  name: string;
  description: string;
  parameters: unknown;
};

type GeminiTool = {
  functionDeclarations?: GeminiFunctionDeclaration[];
  googleSearch?: Record<string, unknown>;
};

type GeminiToolSanitizationOptions = {
  stripNamespace?: boolean;
  toolNameMap?: Map<string, string> | null;
};

const MAX_GEMINI_TOOL_NAME_LENGTH = 64;
const GEMINI_TOOL_HASH_LENGTH = 8;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Gemini/Vertex requires every functionDeclaration.parameters to be an OBJECT-typed schema
 * (#3357: "functionDeclaration parameters schema should be of type OBJECT"). Some clients
 * (e.g. GitHub Copilot's `terminal_last_command`) send a `parameters` that is present but
 * lacks a top-level `type: "object"` — just `{ properties }`, a scalar/array type, or `{}`.
 * Coerce the parameters root to an object schema before it is cleaned; a falsy/non-record
 * schema becomes an empty object schema. Only the top level is touched — nested property
 * schemas are left to cleanJSONSchemaForAntigravity.
 */
function toGeminiParametersSchema(raw: unknown): Record<string, unknown> {
  if (!isRecord(raw)) {
    return { type: "object", properties: {} };
  }
  if (raw.type === "object") {
    return raw;
  }
  return {
    ...raw,
    type: "object",
    properties: isRecord(raw.properties) ? raw.properties : {},
  };
}

function normalizeGeminiToolName(
  name: string,
  options: GeminiToolSanitizationOptions = {}
): string {
  const trimmed = name.trim();
  const namespaceStripped = !options.stripNamespace
    ? trimmed
    : (() => {
        const namespaceIndex = trimmed.indexOf(":");
        return namespaceIndex >= 0 ? trimmed.slice(namespaceIndex + 1) : trimmed;
      })();

  return namespaceStripped
    .replace(/[^a-zA-Z0-9_]/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function buildHashedGeminiToolName(
  baseName: string,
  originalName: string,
  hashLength: number
): string {
  const effectiveBase = baseName || "tool";
  const hash = createHash("sha256").update(originalName).digest("hex").slice(0, hashLength);
  const prefixLength = Math.max(1, MAX_GEMINI_TOOL_NAME_LENGTH - 1 - hash.length);
  return `${effectiveBase.slice(0, prefixLength)}_${hash}`;
}

function findSanitizedNameForOriginal(
  toolNameMap: Map<string, string> | null | undefined,
  originalName: string
): string | null {
  if (!(toolNameMap instanceof Map)) return null;
  for (const [sanitizedName, rawName] of toolNameMap.entries()) {
    if (rawName === originalName) {
      return sanitizedName;
    }
  }
  return null;
}

function isSanitizedNameTaken(
  toolNameMap: Map<string, string> | null | undefined,
  sanitizedName: string,
  originalName: string
): boolean {
  if (!(toolNameMap instanceof Map)) return false;
  const mappedOriginalName = toolNameMap.get(sanitizedName);
  return typeof mappedOriginalName === "string" && mappedOriginalName !== originalName;
}

export function sanitizeGeminiToolName(
  name: string,
  options: GeminiToolSanitizationOptions = {}
): string {
  const normalizedName = normalizeGeminiToolName(name, options) || "tool";
  const toolNameMap = options.toolNameMap instanceof Map ? options.toolNameMap : null;
  const existingSanitizedName = findSanitizedNameForOriginal(toolNameMap, name);
  if (existingSanitizedName) {
    return existingSanitizedName;
  }

  let sanitizedName =
    normalizedName.length <= MAX_GEMINI_TOOL_NAME_LENGTH
      ? normalizedName
      : buildHashedGeminiToolName(normalizedName, name, GEMINI_TOOL_HASH_LENGTH);

  if (isSanitizedNameTaken(toolNameMap, sanitizedName, name)) {
    const conflictingOriginalName = toolNameMap?.get(sanitizedName);
    sanitizedName = buildHashedGeminiToolName(normalizedName, name, GEMINI_TOOL_HASH_LENGTH);
    let hashLength = GEMINI_TOOL_HASH_LENGTH + 2;
    while (isSanitizedNameTaken(toolNameMap, sanitizedName, name) && hashLength <= 32) {
      sanitizedName = buildHashedGeminiToolName(normalizedName, name, hashLength);
      hashLength += 2;
    }

    if (isSanitizedNameTaken(toolNameMap, sanitizedName, name)) {
      sanitizedName = buildHashedGeminiToolName("tool", `${name}:${Date.now()}`, 12);
    }

    console.warn(
      `[GeminiTools] Tool name collision after sanitization: "${name}" conflicts with "${conflictingOriginalName}". Using "${sanitizedName}".`
    );
  }

  toolNameMap?.set(sanitizedName, name);
  return sanitizedName;
}

function toGeminiGoogleSearchTool(tool: Record<string, unknown>): GeminiTool | null {
  if (isRecord(tool.googleSearch)) {
    return { googleSearch: tool.googleSearch };
  }
  if (tool.googleSearch !== undefined) {
    return { googleSearch: {} };
  }

  if (isRecord(tool.google_search)) {
    return { googleSearch: tool.google_search };
  }
  if (tool.google_search !== undefined) {
    return { googleSearch: {} };
  }

  const toolType = typeof tool.type === "string" ? tool.type : "";
  if (
    toolType === "googleSearch" ||
    toolType === "google_search" ||
    toolType === "web_search" ||
    toolType === "web_search_preview"
  ) {
    return { googleSearch: {} };
  }

  return null;
}

export function buildGeminiTools(
  tools: unknown,
  options: GeminiToolSanitizationOptions = {}
): GeminiTool[] | undefined {
  if (!Array.isArray(tools) || tools.length === 0) {
    return undefined;
  }

  const functionDeclarations: GeminiFunctionDeclaration[] = [];
  // Track sanitized names already added to prevent Gemini rejection from duplicate
  // function declaration names (two different raw names that collapse to the same
  // sanitized form, or the same raw name repeated across tool groups).
  const seenToolNames = new Set<string>();
  let googleSearchTool: GeminiTool | null = null;

  for (const rawTool of tools) {
    if (!isRecord(rawTool)) {
      continue;
    }

    const normalizedGoogleSearchTool = toGeminiGoogleSearchTool(rawTool);
    if (normalizedGoogleSearchTool) {
      googleSearchTool = normalizedGoogleSearchTool;
      continue;
    }

    if (Array.isArray(rawTool.functionDeclarations)) {
      for (const fn of rawTool.functionDeclarations) {
        if (!isRecord(fn) || typeof fn.name !== "string" || !fn.name.trim()) {
          continue;
        }

        const sanitizedName = sanitizeGeminiToolName(fn.name, options);
        if (seenToolNames.has(sanitizedName)) continue;
        seenToolNames.add(sanitizedName);
        functionDeclarations.push({
          name: sanitizedName,
          description: typeof fn.description === "string" ? fn.description : "",
          parameters: cleanJSONSchemaForAntigravity(toGeminiParametersSchema(fn.parameters)),
        });
      }
      continue;
    }

    if (typeof rawTool.name === "string" && rawTool.name.trim()) {
      const sanitizedName = sanitizeGeminiToolName(rawTool.name, options);
      if (!seenToolNames.has(sanitizedName)) {
        seenToolNames.add(sanitizedName);
        functionDeclarations.push({
          name: sanitizedName,
          description: typeof rawTool.description === "string" ? rawTool.description : "",
          parameters: cleanJSONSchemaForAntigravity(toGeminiParametersSchema(rawTool.input_schema)),
        });
      }
      continue;
    }

    if (rawTool.type === "function" && isRecord(rawTool.function)) {
      const fn = rawTool.function;
      if (typeof fn.name !== "string" || !fn.name.trim()) {
        continue;
      }

      const sanitizedName = sanitizeGeminiToolName(fn.name, options);
      if (!seenToolNames.has(sanitizedName)) {
        seenToolNames.add(sanitizedName);
        functionDeclarations.push({
          name: sanitizedName,
          description: typeof fn.description === "string" ? fn.description : "",
          parameters: cleanJSONSchemaForAntigravity(toGeminiParametersSchema(fn.parameters)),
        });
      }
    }
  }

  const result: GeminiTool[] = [];

  if (googleSearchTool) {
    return [googleSearchTool];
  }

  if (functionDeclarations.length > 0) {
    result.push({ functionDeclarations });
  }

  return result.length > 0 ? result : undefined;
}

// Pure, self-contained helpers extracted verbatim from ../openai-to-gemini.ts
// (god-file decomposition): historical-tool-context string builders, undefined-
// pruning, thought-signature extraction, tool-name remapping, and the Vertex
// provider check + Antigravity generation-config defaults. No I/O or module state;
// the host imports them back internally (these were module-private — no public API
// change). The GeminiGenerationConfig shape lives here with its only mutator.

export type GeminiGenerationConfig = {
  temperature?: unknown;
  topP?: unknown;
  topK?: unknown;
  maxOutputTokens?: unknown;
  thinkingConfig?: {
    thinkingBudget: number;
    includeThoughts: boolean;
  };
  responseMimeType?: string;
  responseSchema?: unknown;
  stopSequences?: string[] | unknown[];
};

// Vertex AI (and Vertex Partner models) reject the OpenAI-style `id` field inside
// function_call / function_response parts. Detect these by the routed provider id.
export function isVertexGeminiProvider(provider: unknown): boolean {
  return provider === "vertex" || provider === "vertex-partner";
}

type OpenAIToolCallLike = {
  thoughtSignature?: unknown;
  thought_signature?: unknown;
  function?: {
    thoughtSignature?: unknown;
    thought_signature?: unknown;
  };
};

export function buildChangedToolNameMap(
  toolNameMap: Map<string, string>
): Map<string, string> | null {
  const changedEntries = [...toolNameMap.entries()].filter(
    ([sanitizedName, originalName]) => sanitizedName !== originalName
  );
  return changedEntries.length > 0 ? new Map(changedEntries) : null;
}

export function extractClientThoughtSignature(toolCall: unknown): string | null {
  if (!toolCall || typeof toolCall !== "object") return null;
  const candidate = toolCall as OpenAIToolCallLike;

  const signature =
    candidate.thoughtSignature ||
    candidate.thought_signature ||
    candidate.function?.thoughtSignature ||
    candidate.function?.thought_signature ||
    null;
  return typeof signature === "string" && signature.length > 0 ? signature : null;
}

export function deepCleanUndefined(value: unknown, depth = 0): void {
  if (depth > 10 || !value || typeof value !== "object") {
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) {
      deepCleanUndefined(item, depth + 1);
    }
  } else {
    const obj = value as Record<string, unknown>;
    for (const key of Object.keys(obj)) {
      const val = obj[key];
      if (typeof val === "string" && val === "[undefined]") {
        delete obj[key];
      } else {
        deepCleanUndefined(val, depth + 1);
      }
    }
  }
}

export function applyAntigravityGenerationDefaults(generationConfig: GeminiGenerationConfig) {
  const config = { ...generationConfig };
  if (config.topK === undefined) {
    config.topK = 40;
  }
  if (config.topP === undefined) {
    config.topP = 1;
  }

  const thinkingBudget = Number(config.thinkingConfig?.thinkingBudget);
  const maxOutputTokens = Number(config.maxOutputTokens);
  if (
    Number.isFinite(thinkingBudget) &&
    thinkingBudget > 0 &&
    (!Number.isFinite(maxOutputTokens) || maxOutputTokens <= thinkingBudget)
  ) {
    config.maxOutputTokens = Math.floor(thinkingBudget) + 1;
  }

  return config;
}

export function stringifyHistoricalToolArguments(value: unknown): string {
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value ?? {});
  } catch {
    return String(value ?? "{}");
  }
}

export function buildInertHistoricalToolCallText(name: string | undefined, args: unknown): string {
  const toolName = name || "unknown";
  return `[tool_history_call: ${toolName}] ${stringifyHistoricalToolArguments(args || "{}")}`;
}

export function buildInertHistoricalToolResponseText(name: string, response: unknown): string {
  return `[tool_history_result: ${name || "unknown"}] ${typeof response === "string" ? response : stringifyHistoricalToolArguments(response)}`;
}

export function escapeHistoricalContextAttribute(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
}

export function escapeHistoricalContextContent(value: string): string {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}

export function buildHistoricalToolResultContext(name: string, response: unknown): string {
  const source = escapeHistoricalContextAttribute(name || "unknown");
  const rawResult =
    typeof response === "string" ? response : stringifyHistoricalToolArguments(response);
  const result = escapeHistoricalContextContent(rawResult);
  return [
    `<previous_tool_result_context source="${source}">`,
    result,
    "</previous_tool_result_context>",
  ].join("\n");
}

import { register } from "../registry.ts";
import { FORMATS } from "../formats.ts";
import { adjustMaxTokens } from "../helpers/maxTokensHelper.ts";
import { fixToolPairs } from "../../services/contextManager.ts";
import { normalizeEffort } from "@/shared/reasoning/effortStandardization";

type JsonRecord = Record<string, unknown>;

// Convert Antigravity request to OpenAI format
// Antigravity body: { project, model, userAgent, requestType, requestId, request: { contents, systemInstruction, tools, toolConfig, generationConfig, sessionId } }
export function antigravityToOpenAIRequest(model, body, stream) {
  const req = body.request || body;
  const result: {
    model: string;
    messages: JsonRecord[];
    stream: unknown;
    tools?: JsonRecord[];
    [key: string]: unknown;
  } = {
    model: model,
    messages: [],
    stream: stream,
  };

  // Explicit per-alias reasoning-effort override (Antigravity MITM layer only —
  // `src/mitm/aliasConfig.ts` / `src/mitm/_internal/aliasConfig.cjs`). Set at the same
  // envelope level as `model` (top-level `body`, sibling of `.request`), so it survives
  // regardless of which cloudcode envelope shape the caller used. When present it takes
  // priority over the thinkingConfig-derived value below: an explicit "none" suppresses
  // reasoning_effort entirely even if Antigravity's own thinkingConfig requested thinking;
  // any other explicit tier is emitted verbatim instead of the coarse budget-based guess.
  // Ported from upstream decolua/9router#2584 ("add Antigravity reasoning effort overrides").
  const effortOverride = normalizeEffort((body as JsonRecord).reasoningEffortOverride);

  // Generation config
  if (req.generationConfig) {
    const config = req.generationConfig;
    if (config.maxOutputTokens) {
      const tempBody = { max_tokens: config.maxOutputTokens, tools: req.tools };
      result.max_tokens = adjustMaxTokens(tempBody);
    }
    if (config.temperature !== undefined) {
      result.temperature = config.temperature;
    }
    if (config.topP !== undefined) {
      result.top_p = config.topP;
    }
    if (config.topK !== undefined) {
      result.top_k = config.topK;
    }

    // Thinking config → reasoning_effort (skipped when an explicit override is present).
    if (effortOverride === undefined && config.thinkingConfig) {
      const budget = config.thinkingConfig.thinkingBudget || 0;
      if (budget > 0) {
        if (budget <= 2048) {
          result.reasoning_effort = "low";
        } else if (budget <= 16384) {
          result.reasoning_effort = "medium";
        } else {
          result.reasoning_effort = "high";
        }
      }
    }
  }

  if (effortOverride !== undefined && effortOverride !== "none") {
    result.reasoning_effort = effortOverride;
  } else if (effortOverride === "none") {
    delete result.reasoning_effort;
  }

  // System instruction
  if (req.systemInstruction) {
    const systemText = extractText(req.systemInstruction);
    if (systemText) {
      result.messages.push({ role: "system", content: systemText });
    }
  }

  // Convert contents to messages
  if (req.contents && Array.isArray(req.contents)) {
    for (const content of req.contents) {
      const converted = convertContent(content);
      if (converted) {
        if (Array.isArray(converted)) {
          result.messages.push(...converted);
        } else {
          result.messages.push(converted);
        }
      }
    }
  }

  // Tools
  if (req.tools && Array.isArray(req.tools)) {
    result.tools = [];
    for (const tool of req.tools) {
      if (tool.functionDeclarations) {
        for (const func of tool.functionDeclarations) {
          result.tools.push({
            type: "function",
            function: {
              name: func.name,
              description: func.description || "",
              parameters: cleanSchemaPreservingRequired(func.parameters) || {
                type: "object",
                properties: {},
              },
            },
          });
        }
      }
    }
  }

  // Guard against orphan tool_result/tool_use pairs (#6026). Antigravity IDE can ship a
  // truncated history whose first turn is a `functionResponse` with no preceding
  // `functionCall`. Left untouched, that becomes an orphan `role:"tool"` message here and,
  // after the openai→claude step, an orphan `tool_result` block — which Anthropic (Vertex
  // `claude-opus-4.6`) rejects with `unexpected tool_use_id found in tool_result blocks`.
  // `fixToolPairs` strips only genuine orphans and is idempotent on well-formed histories,
  // so paired functionCall/functionResponse turns pass through unchanged. This mirrors the
  // executor-side guard in `executors/base.ts` / `services/claudeCodeCompatible.ts`; the
  // Antigravity MITM path did not run it (no `fixToolPairs` under `src/mitm/`). We do NOT
  // run `fixToolAdjacency` here because this stage still emits OpenAI-format messages and
  // Claude's adjacency rule is enforced downstream per provider.
  result.messages = fixToolPairs(result.messages) as JsonRecord[];

  return result;
}

// Recursively convert Antigravity schema types (OBJECT, STRING, etc.) to lowercase
// and strip unsupported fields like enumDescriptions.
function normalizeSchemaTypes(schema: unknown): unknown {
  if (!schema || typeof schema !== "object") return schema;

  const result: JsonRecord = Array.isArray(schema)
    ? ([...(schema as unknown[])] as unknown as JsonRecord)
    : { ...(schema as JsonRecord) };

  if (typeof result.type === "string") {
    result.type = result.type.toLowerCase();
  }

  // Strip enumDescriptions — not supported by upstream APIs
  delete result.enumDescriptions;

  if (result.properties && typeof result.properties === "object") {
    const normalized: JsonRecord = {};
    for (const [key, val] of Object.entries(result.properties as JsonRecord)) {
      normalized[key] = normalizeSchemaTypes(val);
    }
    result.properties = normalized;
  }

  if (result.items) {
    result.items = normalizeSchemaTypes(result.items);
  }

  return result;
}

// Clean a JSON Schema for Antigravity while PRESERVING the `required` array at every level.
// Unlike the type-lowering pass alone, this strips JSON Schema Draft 2020-12 meta keywords
// ($schema, $defs, $ref, additionalProperties, patternProperties, title, x-*, ...) that the
// Antigravity upstream does not accept, yet keeps `required` so the model still treats
// mandatory tool arguments as mandatory. Clients such as OpenCode send full Draft 2020-12
// tool schemas; dropping `required` lets the model call tools without their required args.
function cleanSchemaPreservingRequired(schema: unknown): unknown {
  if (!schema || typeof schema !== "object") return schema;

  // Reuse the existing recursion to lowercase types + strip enumDescriptions, then
  // remove draft-meta keywords and reconcile `required` against the surviving properties.
  const normalized = normalizeSchemaTypes(structuredClone(schema));
  stripDraftMeta(normalized);
  preserveRequired(normalized);
  return normalized;
}

// Draft 2020-12 / JSON Schema meta keywords the Antigravity upstream does not accept.
const DRAFT_META_KEYS = new Set([
  "$schema",
  "$defs",
  "definitions",
  "$ref",
  "$comment",
  "const",
  "additionalProperties",
  "propertyNames",
  "patternProperties",
  "title",
]);

function stripDraftMeta(obj: unknown): void {
  if (!obj || typeof obj !== "object") return;
  if (Array.isArray(obj)) {
    for (const item of obj) stripDraftMeta(item);
    return;
  }
  const record = obj as JsonRecord;
  for (const key of Object.keys(record)) {
    if (DRAFT_META_KEYS.has(key) || key.startsWith("x-")) {
      delete record[key];
    }
  }
  for (const value of Object.values(record)) {
    if (value && typeof value === "object") stripDraftMeta(value);
  }
}

// Preserve `required` even when referenced fields were stripped from constraint blocks.
// At each node where both `required` and `properties` are present, keep only the entries
// that still exist in `properties`; drop `required` entirely if none survive. This avoids
// emitting a `required` array that references fields removed by stripDraftMeta.
function preserveRequired(obj: unknown): void {
  if (!obj || typeof obj !== "object") return;
  if (Array.isArray(obj)) {
    for (const item of obj) preserveRequired(item);
    return;
  }
  const record = obj as JsonRecord;
  if (Array.isArray(record.required) && record.properties && typeof record.properties === "object") {
    const properties = record.properties as JsonRecord;
    const valid = (record.required as unknown[]).filter(
      (field) =>
        typeof field === "string" &&
        Object.prototype.hasOwnProperty.call(properties, field)
    );
    if (valid.length === 0) {
      delete record.required;
    } else {
      record.required = valid;
    }
  }
  for (const value of Object.values(record)) {
    if (value && typeof value === "object") preserveRequired(value);
  }
}

// Convert Antigravity content to OpenAI message
// Handles: text, thought, thoughtSignature, functionCall, functionResponse, inlineData
function convertContent(content) {
  const role =
    content.role === "model" ? "assistant" : content.role === "user" ? "user" : content.role;

  if (!content.parts || !Array.isArray(content.parts)) {
    return null;
  }

  const textParts = [];
  const toolCalls = [];
  const toolResults = [];
  let reasoningContent = "";

  for (const part of content.parts) {
    // Thinking content (thought: true)
    if (part.thought === true && part.text) {
      reasoningContent += part.text;
      continue;
    }

    // Text with thoughtSignature = regular text after thinking.
    // Skip empty text — Anthropic rejects empty content blocks with a 400.
    if (part.thoughtSignature && part.text !== undefined) {
      if (part.text) {
        textParts.push({ type: "text", text: part.text });
      }
      continue;
    }

    // Regular text — skip empty strings (Anthropic rejects empty content blocks).
    if (part.text !== undefined && part.text !== "") {
      textParts.push({ type: "text", text: part.text });
    }

    // Inline data (images)
    if (part.inlineData) {
      textParts.push({
        type: "image_url",
        image_url: {
          url: `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`,
        },
      });
    }

    // Function call
    if (part.functionCall) {
      toolCalls.push({
        id: part.functionCall.id || `call_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
        type: "function",
        function: {
          name: part.functionCall.name,
          arguments: JSON.stringify(part.functionCall.args || {}),
        },
      });
    }

    // Function response → collect all, each becomes a separate tool message
    if (part.functionResponse) {
      toolResults.push({
        role: "tool",
        tool_call_id: part.functionResponse.id || part.functionResponse.name,
        content: JSON.stringify(
          part.functionResponse.response?.result || part.functionResponse.response || {}
        ),
      });
    }
  }

  // Function responses may be co-located with function calls / text / reasoning in
  // the same content. Emit the tool messages AND the accompanying assistant message so
  // nothing is dropped (previously only the tool messages survived).
  if (toolResults.length > 0) {
    if (toolCalls.length > 0 || textParts.length > 0 || reasoningContent) {
      const assistantMsg: JsonRecord = { role: "assistant" };
      if (textParts.length > 0) {
        assistantMsg.content =
          textParts.length === 1 && textParts[0].type === "text"
            ? textParts[0].text
            : textParts;
      }
      if (reasoningContent) {
        assistantMsg.reasoning_content = reasoningContent;
      }
      if (toolCalls.length > 0) {
        assistantMsg.tool_calls = toolCalls;
      }
      return [...toolResults, assistantMsg];
    }
    return toolResults;
  }

  // Assistant with tool calls
  if (toolCalls.length > 0) {
    const msg: JsonRecord = { role: "assistant" };
    if (textParts.length > 0) {
      msg.content =
        textParts.length === 1 && textParts[0].type === "text" ? textParts[0].text : textParts;
    }
    if (reasoningContent) {
      msg.reasoning_content = reasoningContent;
    }
    msg.tool_calls = toolCalls;
    return msg;
  }

  // Regular message
  if (textParts.length > 0 || reasoningContent) {
    const msg: JsonRecord = { role };
    if (textParts.length > 0) {
      msg.content =
        textParts.length === 1 && textParts[0].type === "text" ? textParts[0].text : textParts;
    }
    if (reasoningContent) {
      msg.reasoning_content = reasoningContent;
    }
    return msg;
  }

  return null;
}

// Extract text from systemInstruction
function extractText(instruction) {
  if (typeof instruction === "string") return instruction;
  if (instruction.parts && Array.isArray(instruction.parts)) {
    return instruction.parts.map((p) => p.text || "").join("");
  }
  return "";
}

// Register
register(FORMATS.ANTIGRAVITY, FORMATS.OPENAI, antigravityToOpenAIRequest, null);

import { z } from "zod";

/**
 * Standardization layer for the canonical `effort` + `thinking` request params (#6241).
 *
 * OmniRoute already has a mature, per-provider reasoning-mapping pipeline: the translators
 * consume `reasoning_effort` / `reasoning.effort` / `thinking` and fan them out to the
 * Anthropic thinking blocks, Gemini `thinkingConfig`, xAI `reasoning.effort`, and the
 * Responses API. This module is a THIN normalization layer on top of that plumbing — it
 * does NOT re-implement any provider mapping. It only exposes a single, documented,
 * provider-agnostic pair of request fields and folds them onto the fields the existing
 * mappers already read.
 *
 * The provider-agnostic vocabulary remains five values. Provider-native additions such as
 * Codex GPT-5.6 Max and Ultra are exposed separately without widening this request contract.
 */
export const CANONICAL_EFFORT_VALUES = ["none", "low", "medium", "high", "xhigh"] as const;

export type CanonicalEffort = (typeof CANONICAL_EFFORT_VALUES)[number];

/** Use provider-native GPT-5.6 effort levels without widening the global request vocabulary. */
export function extendCodexGpt56EffortValues(
  provider: string | null | undefined,
  model: string | null | undefined,
  baseValues: readonly string[]
): string[] {
  const values = [...baseValues];
  const normalizedProvider = provider?.trim().toLowerCase();
  const normalizedModel = model
    ?.trim()
    .toLowerCase()
    .replace(/^(?:codex|cx)\//, "");
  if (!normalizedModel || (normalizedProvider !== "codex" && normalizedProvider !== "cx")) {
    return values;
  }

  const match = normalizedModel.match(
    /^gpt-5\.6-(sol|terra|luna)(?:-(?:none|low|medium|high|xhigh|max|ultra))?$/
  );
  if (!match) return values;

  const nativeValues = ["low", "medium", "high", "xhigh", "max"];
  return match[1] === "luna" ? nativeValues : [...nativeValues, "ultra"];
}

/**
 * UI-facing tier synonyms mapped onto the canonical set. The issue (#6241) requested a
 * 5-tier UI vocabulary (Low / Medium / High / Extra / Max); that request collapses onto
 * the existing 5-value canonical set. "extra" and "max" are both synonyms for the top
 * reasoning tier and map to canonical `xhigh`. The per-provider mappers already down-shift
 * `xhigh` to `high` for models that do not support it (see
 * `open-sse/translator/request/openai-to-claude.ts`), so a caller can always request the
 * highest tier without knowing which models support `xhigh`.
 */
const EFFORT_TIER_ALIASES: Record<string, CanonicalEffort> = {
  extra: "xhigh",
  max: "xhigh",
};

/**
 * Normalize an arbitrary effort value onto the canonical vocabulary. Accepts the canonical
 * values plus the UI tier synonyms (`extra`/`max` → `xhigh`), case-insensitively. Returns
 * `undefined` for anything unrecognized so callers can leave the request untouched.
 */
export function normalizeEffort(value: unknown): CanonicalEffort | undefined {
  if (typeof value !== "string") return undefined;
  const lowered = value.trim().toLowerCase();
  if (!lowered) return undefined;
  if (lowered in EFFORT_TIER_ALIASES) return EFFORT_TIER_ALIASES[lowered];
  return (CANONICAL_EFFORT_VALUES as readonly string[]).includes(lowered)
    ? (lowered as CanonicalEffort)
    : undefined;
}

/**
 * Zod schema for the canonical `effort` request field. Accepts the canonical values plus
 * the UI tier synonyms (case-insensitively) and normalizes them onto the canonical set.
 * Unrecognized strings are rejected with a clear enum error.
 */
export const effortRequestSchema = z.preprocess(
  (value) => normalizeEffort(value) ?? value,
  z.enum(CANONICAL_EFFORT_VALUES)
);

/**
 * Zod schema for the canonical `thinking` request field: a simple boolean toggle. Kept as
 * a union with an object so the existing Anthropic-style `thinking: { type, budget_tokens }`
 * object shape that clients already send keeps validating (backward compatible) — the
 * normalizer only acts on the boolean form.
 */
export const thinkingRequestSchema = z.union([z.boolean(), z.record(z.string(), z.unknown())]);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Fold the canonical `effort` / `thinking` request params onto the per-provider reasoning
 * fields the existing translators already consume (`reasoning_effort`, `reasoning.effort`,
 * `thinking`). Pure function — returns the same reference untouched when there is nothing
 * to normalize, otherwise a shallow copy with the derived fields populated.
 *
 * Backward compatibility rules (an explicit client signal ALWAYS wins):
 *  - `reasoning_effort` / `reasoning.effort` explicitly set by the client are never
 *    overwritten by the canonical `effort`.
 *  - An explicit object-shaped `thinking` (the Anthropic `{ type, budget_tokens }` config)
 *    is never overwritten by the canonical boolean `thinking`.
 */
export function normalizeReasoningRequest<T>(body: T): T {
  if (!isPlainObject(body)) return body;

  const canonicalEffort = normalizeEffort(body.effort);
  const canonicalThinking = body.thinking;
  const hasCanonicalThinkingBool = typeof canonicalThinking === "boolean";

  if (canonicalEffort === undefined && !hasCanonicalThinkingBool) return body;

  const reasoning = body.reasoning;
  const clientSetReasoningEffort = body.reasoning_effort !== undefined;
  const clientSetReasoningObjEffort = isPlainObject(reasoning) && reasoning.effort !== undefined;

  const next: Record<string, unknown> = { ...body };

  // Canonical effort → the fields the mappers read. Skip entirely if the client already
  // expressed a reasoning effort (either shape) so client intent is preserved.
  if (canonicalEffort !== undefined && !clientSetReasoningEffort && !clientSetReasoningObjEffort) {
    next.reasoning_effort = canonicalEffort;
    next.reasoning = {
      ...(isPlainObject(reasoning) ? reasoning : {}),
      effort: canonicalEffort,
    };
  }

  // Canonical boolean `thinking` → keep the truthy toggle the mappers read. Only when the
  // client did NOT provide an explicit object-shaped thinking config (that always wins).
  if (hasCanonicalThinkingBool) {
    next.thinking = canonicalThinking;
  }

  return next as T;
}

/**
 * Translator: OpenAI Responses API -> OpenAI Chat Completions
 *
 * Responses API uses: { input: [...], instructions: "..." }
 * Chat API uses: { messages: [...] }
 */
import { isOpenAIResponsesStoreEnabled } from "@/lib/providers/requestDefaults";
import { FORMATS } from "../formats.ts";
import { register } from "../registry.ts";
import { normalizeResponsesInputForChat } from "../../utils/responsesInputNormalization.ts";
import {
  getRegisteredProviders,
  requiresPlainStringContent,
} from "../../config/providerRegistry.ts";
import { collectResponsesTools } from "./openai-responses/additionalTools.ts";
import { flattenNamespaceToolName } from "./openai-responses/namespaceFlatten.ts";
import { openaiToOpenAIResponsesRequest } from "./openai-responses/toResponses.ts";
import {
  JsonRecord,
  RESPONSES_STORE_MARKER,
  COPILOT_REASONING_SUMMARY_MARKER,
  WEB_SEARCH_TOOL_TYPES,
  TOOL_SEARCH_TOOL_TYPES,
  IMAGE_GENERATION_TOOL_TYPES,
  toRecord,
  toString,
  normalizeVerbosity,
  normalizeResponsesReasoningEffort,
  shouldRequestClaudeSummarizedThinking,
  unsupportedFeature,
} from "./openai-responses/helpers.ts";

// chat -> Responses direction extracted to a pure leaf; re-exported for external
// importers (tests). Host imports it back for registration below.
export { openaiToOpenAIResponsesRequest } from "./openai-responses/toResponses.ts";

/**
 * #8459: Convert a tool output content-part array to a safe string for Chat Completions
 * tool content. Responses API tool outputs can contain `input_image` parts which have no
 * equivalent in Chat Completions `tool` messages — JSON.stringify would embed the raw
 * base64 as inert text. Instead, extract text parts and replace images with a placeholder.
 *
 * @param output - The tool output value (string, array of content parts, or other JSON)
 * @returns A plain string safe for Chat Completions `tool` message content.
 */
function toolOutputContentToString(output: unknown): string {
  if (typeof output === "string") return output;
  if (!Array.isArray(output)) return JSON.stringify(output);

  const parts: string[] = [];
  for (const item of output) {
    if (typeof item !== "object" || item === null) {
      parts.push(String(item));
      continue;
    }
    const rec = item as Record<string, unknown>;
    const type = typeof rec.type === "string" ? rec.type : "";
    if (type === "input_text" || type === "output_text") {
      const text = typeof rec.text === "string" ? rec.text : "";
      if (text) parts.push(text);
    } else if (type === "input_image") {
      parts.push("[Image omitted: not supported on Chat Completions tool results]");
    } else {
      // Unknown part type — stringify as fallback
      try {
        parts.push(JSON.stringify(item));
      } catch {
        parts.push(String(item));
      }
    }
  }
  return parts.join("\n");
}

/**
 * Convert OpenAI Responses API request to OpenAI Chat Completions format
 */
export function openaiResponsesToOpenAIRequest(
  model: unknown,
  body: unknown,
  stream: unknown,
  credentials: unknown
): unknown {
  void stream;
  void credentials;
  const collapseToPlainString = requiresPlainStringContent(extractProviderHint(model));

  const root = toRecord(body);
  if (root.input === undefined) return body;
  const credentialRecord = toRecord(credentials);
  const storeEnabled = isOpenAIResponsesStoreEnabled(credentialRecord.providerSpecificData);
  const rawInputItems = normalizeResponsesInputForChat(root.input);

  // Tools may be declared at the Responses top level or in one or more
  // `additional_tools` input items. Normalize both forms before validation/conversion so
  // every downgraded provider receives the same available tool set.
  const tools = collectResponsesTools(root.tools, rawInputItems);
  if (tools.length > 0) {
    for (const toolValue of tools) {
      const tool = toRecord(toolValue);
      const toolType = toString(tool.type);
      // Allow: function tools, tools already in Chat format (have .function property), CLI subagent tools,
      // namespace tools (MCP tool groups used by Codex/OpenAI Responses API), and web_search server tools
      // (Anthropic versioned: web_search_20250305, web_search_20250101, etc. — or plain web_search).
      // tool_search is a Responses API built-in sent by newer Codex clients; silently skip it here
      // (it will be filtered out during tools conversion below).
      if (
        toolType &&
        toolType !== "function" &&
        toolType !== "custom" &&
        toolType !== "command" &&
        toolType !== "namespace" &&
        toolType !== "local_shell" &&
        !WEB_SEARCH_TOOL_TYPES.test(toolType) &&
        !TOOL_SEARCH_TOOL_TYPES.test(toolType) &&
        !IMAGE_GENERATION_TOOL_TYPES.test(toolType) &&
        !tool.function
      ) {
        throw unsupportedFeature(
          `Unsupported Responses API feature: ${toolType} tool type is not supported by omniroute`
        );
      }
    }
  }

  const result: JsonRecord = { ...root };

  // Request-scoped response-side identity for Responses namespace child tools.
  // The Chat wire `tool.function.name` is the namespace-qualified name (#8295:
  // folding the namespace in makes cross-namespace leaf collisions structurally
  // impossible), and the original `{namespace, name}` pair is retained in this
  // side-band map so the response translator can emit codex-compatible
  // `namespace` + `name` fields without reparsing the wire name.
  const namespaceToolIdentityMap = new Map<string, { namespace: string; name: string }>();

  // #7533: `verbosity` and `prompt_cache_key` are GPT-5/OpenAI-only Chat Completions
  // parameters. A strict-protocol non-OpenAI upstream (NVIDIA confirmed by the reporter;
  // likely also GLM/Kimi/Deepseek direct endpoints) 400s on unrecognized top-level
  // parameters, so they must only survive the downgrade when the destination really is
  // an OpenAI-operated endpoint.
  //
  // Allowlist, NOT a denylist: over-stripping costs a cache hit, over-preserving costs a
  // hard 400. `codex` is in the list because it IS an OpenAI upstream
  // (chatgpt.com/backend-api/codex) and is precisely the destination #517 needed
  // `prompt_cache_key` preserved for — /v1/responses runs every request through this
  // downgrade (handleResponsesCore -> convertResponsesApiFormat) regardless of provider,
  // so gating on "openai" alone silently re-broke Codex prompt caching. Other
  // OpenAI-compatible passthroughs (e.g. Azure OpenAI) are deliberately NOT assumed in —
  // add them only with evidence that the endpoint accepts these fields.
  const OPENAI_PARAM_DESTINATIONS = new Set(["openai", "codex"]);
  const isOpenAIDestination = OPENAI_PARAM_DESTINATIONS.has(toString(credentialRecord.provider));

  // GPT-5 verbosity: Responses `text.verbosity` → Chat Completions top-level `verbosity`.
  // Chat has no `text` wrapper, so carry the level across and drop the Responses-only
  // `text` object (a strict Chat endpoint 400s on unknown fields).
  const responsesVerbosity = normalizeVerbosity(toRecord(result.text).verbosity);
  if (responsesVerbosity && isOpenAIDestination) result.verbosity = responsesVerbosity;
  const responsesTextFormat = toRecord(toRecord(result.text).format);
  if (responsesTextFormat.type === "json_schema" && responsesTextFormat.schema !== undefined) {
    const jsonSchema: JsonRecord = {
      name: toString(responsesTextFormat.name, "response"),
      schema: responsesTextFormat.schema,
    };
    if (responsesTextFormat.description !== undefined) {
      jsonSchema.description = responsesTextFormat.description;
    }
    if (responsesTextFormat.strict !== undefined) jsonSchema.strict = responsesTextFormat.strict;
    result.response_format = { type: "json_schema", json_schema: jsonSchema };
  } else if (responsesTextFormat.type === "json_object") {
    result.response_format = { type: "json_object" };
  }
  delete result.text;

  // background: true requests a deferred Responses API run (the upstream
  // returns 202 with response_id and the client polls GET /responses/<id>).
  // OmniRoute is a forward proxy that streams responses synchronously —
  // implementing the queue/poll contract would require persistence and a
  // separate retrieval surface. Degrade: log a marker when true was
  // actually requested (operators can observe clients that should be
  // reconfigured) and strip the flag. Clients that set background=true
  // opportunistically (Capy Captain Pro, Codex agents) work unchanged.
  // Clients that strictly require the async contract still observe a
  // completed response on the first poll and can adapt.
  if (result.background === true) {
    const providerStr = toString(credentialRecord.provider);
    const modelStr = toString(model);
    console.warn(
      `BACKGROUND_DEGRADE provider=${providerStr || "unknown"} model=${modelStr || "unknown"}`
    );
  }
  if (result.background !== undefined) {
    delete result.background;
  }
  const messages: JsonRecord[] = [];
  result.messages = messages;

  // Convert instructions to system message
  if (typeof root.instructions === "string" && root.instructions.length > 0) {
    messages.push({ role: "system", content: root.instructions });
  }

  // Group items by conversation turn
  let currentAssistantMsg: JsonRecord | null = null;
  let pendingToolResults: JsonRecord[] = [];

  // Upstream providers reject messages:[] with "400: at least one message is required".
  // When the client sends input:[] (empty), inject a placeholder user message — mirrors
  // upstream 9router#419 (and the existing empty-string handling elsewhere in this file).
  const inputItems: unknown[] =
    rawInputItems.length === 0
      ? [{ type: "message", role: "user", content: [{ type: "input_text", text: "..." }] }]
      : rawInputItems;
  for (const itemValue of inputItems) {
    const item = toRecord(itemValue);

    // Determine item type - Droid CLI sends role-based items without 'type' field
    // Fallback: if no type but has role property, treat as message
    const itemType = toString(item.type) || (item.role ? "message" : "");

    if (itemType === "message") {
      // Flush pending assistant message with tool calls
      if (currentAssistantMsg) {
        messages.push(currentAssistantMsg);
        currentAssistantMsg = null;
      }

      // Flush pending tool results
      if (pendingToolResults.length > 0) {
        for (const toolResult of pendingToolResults) {
          messages.push(toolResult);
        }
        pendingToolResults = [];
      }

      // Convert content: input_text -> text, output_text -> text
      const content = Array.isArray(item.content)
        ? item.content.map((contentValue) => {
            const contentItem = toRecord(contentValue);
            if (contentItem.type === "input_text") {
              return { type: "text", text: toString(contentItem.text) };
            }
            if (contentItem.type === "output_text") {
              return { type: "text", text: toString(contentItem.text) };
            }
            if (contentItem.type === "refusal") {
              return { type: "text", text: toString(contentItem.refusal) };
            }
            if (contentItem.type === "input_image") {
              const imgResult: JsonRecord = {
                type: "image_url",
                image_url: { url: toString(contentItem.image_url) },
              };
              if (contentItem.detail !== undefined) {
                (imgResult.image_url as JsonRecord).detail = contentItem.detail;
              }
              return imgResult;
            }
            if (contentItem.type === "input_file") {
              const fileObj: JsonRecord = {};
              if (contentItem.file_data !== undefined) fileObj.file_data = contentItem.file_data;
              if (contentItem.file_id !== undefined) fileObj.file_id = contentItem.file_id;
              if (contentItem.file_url !== undefined) fileObj.file_url = contentItem.file_url;
              if (contentItem.filename !== undefined) fileObj.filename = contentItem.filename;
              return { type: "file", file: fileObj };
            }
            return contentValue;
          })
        : item.content;

      messages.push({ role: toString(item.role), content });
      continue;
    }

    if (itemType === "function_call") {
      // Skip tool calls with empty names to avoid infinite placeholder_tool loops
      const fnName = toString(item.name).trim();
      if (!fnName) {
        continue;
      }
      // #2893: Skip tool calls with an empty call_id — they can never be matched
      // to their function_call_output, so the upstream rejects the orphaned tool
      // result with "Messages with role 'tool' must be a response to a preceding
      // message with 'tool_calls'". Dropping the unmatched pair avoids the 400.
      if (!toString(item.call_id).trim()) {
        continue;
      }

      // Start or append assistant message with tool_calls
      if (!currentAssistantMsg) {
        currentAssistantMsg = {
          role: "assistant",
          content: null,
          tool_calls: [],
        };
      }

      const toolCalls = Array.isArray(currentAssistantMsg.tool_calls)
        ? currentAssistantMsg.tool_calls
        : [];
      toolCalls.push({
        id: toString(item.call_id),
        type: "function",
        function: {
          name: fnName,
          arguments:
            typeof item.arguments === "string"
              ? item.arguments
              : JSON.stringify(item.arguments ?? {}),
        },
      });
      currentAssistantMsg.tool_calls = toolCalls;
      continue;
    }

    if (itemType === "function_call_output") {
      // Flush assistant message first if present
      if (currentAssistantMsg) {
        messages.push(currentAssistantMsg);
        currentAssistantMsg = null;
      }

      // Flush pending tool results first
      if (pendingToolResults.length > 0) {
        for (const toolResult of pendingToolResults) {
          messages.push(toolResult);
        }
        pendingToolResults = [];
      }

      // Add tool result immediately
      messages.push({
        role: "tool",
        tool_call_id: toString(item.call_id),
        content: toolOutputContentToString(item.output),
      });
      continue;
    }

    if (itemType === "custom_tool_call") {
      // Codex custom tool call (e.g. apply_patch): `input` is a raw string, not JSON
      // arguments. Map it onto the assistant tool_calls list as a function call whose
      // arguments wrap the raw string as { input }, matching the { input: string }
      // schema the request-side tools normalization advertises for custom tools.
      const fnName = toString(item.name).trim();
      if (!fnName) {
        continue;
      }
      if (!currentAssistantMsg) {
        currentAssistantMsg = {
          role: "assistant",
          content: null,
          tool_calls: [],
        };
      }
      const toolCalls = Array.isArray(currentAssistantMsg.tool_calls)
        ? currentAssistantMsg.tool_calls
        : [];
      toolCalls.push({
        id: toString(item.call_id),
        type: "function",
        function: {
          name: fnName,
          arguments: JSON.stringify({ input: item.input }),
        },
      });
      currentAssistantMsg.tool_calls = toolCalls;
      continue;
    }

    if (itemType === "custom_tool_call_output") {
      // Result of a custom tool call — translate the same way as function_call_output.
      if (currentAssistantMsg) {
        messages.push(currentAssistantMsg);
        currentAssistantMsg = null;
      }
      if (pendingToolResults.length > 0) {
        for (const toolResult of pendingToolResults) {
          messages.push(toolResult);
        }
        pendingToolResults = [];
      }
      // Unwrap JSON-wrapped output {"output":"...","metadata":{...}} → plain string.
      // #8459: handle content-part arrays that may contain input_image without
      // stringifying raw base64 as text.
      const rawOut = toolOutputContentToString(item.output);
      let toolContent = rawOut;
      try {
        const parsed = JSON.parse(rawOut);
        if (parsed && typeof parsed.output === "string") toolContent = parsed.output;
      } catch {
        // Not JSON — keep the raw output as the tool content.
      }
      messages.push({
        role: "tool",
        tool_call_id: toString(item.call_id),
        content: toolContent,
      });
      continue;
    }

    if (itemType === "reasoning") {
      // Skip reasoning items - they are display-only metadata
      continue;
    }

    // Skip tool_search_call items. These are Responses-API-only metadata items
    // emitted by Codex's dynamic tool-search optimization: they record that the
    // model queried a subset of available tools, but carry no content that Chat
    // Completions can represent. Throwing here would break every multi-turn
    // conversation where Codex previously used tool_search (the whole session
    // would carry tool_search_call items forward in `input`). Skipping matches
    // the reasoning-item policy: display-only metadata, no chat side-effect.
    if (itemType === "tool_search_call" || itemType === "tool_search_result") {
      continue;
    }

    if (itemType === "additional_tools") {
      // Already consumed by collectResponsesTools() before message conversion.
      continue;
    }

    throw unsupportedFeature(
      `Unsupported Responses API feature: input item type '${itemType || "missing"}' cannot be represented in Chat Completions`
    );
  }

  // Flush remainder
  if (currentAssistantMsg) {
    messages.push(currentAssistantMsg);
  }
  if (pendingToolResults.length > 0) {
    for (const toolResult of pendingToolResults) {
      messages.push(toolResult);
    }
  }

  // Convert tools format
  if (tools.length > 0) {
    result.tools = tools
      .filter((toolValue) => {
        const tool = toRecord(toolValue);
        const toolType = toString(tool.type);
        // image_generation (#2950) is a Responses API server-side hosted tool with no
        // Chat Completions equivalent; drop it silently. tool_search (#2766) used to be
        // dropped here too, but it is a CLIENT-executed tool (Codex sends it with
        // `execution: "client"`) — see the flatMap branch below (#7532) for why it is
        // now mapped onto a Chat function tool instead of discarded.
        return !IMAGE_GENERATION_TOOL_TYPES.test(toolType);
      })
      .flatMap((toolValue) => {
        const tool = toRecord(toolValue);
        if (tool.function) return toolValue;
        const toolType = toString(tool.type);
        // MCP tool groups: Codex/OpenAI Responses clients declare each MCP server as a
        // `namespace` tool — { type:"namespace", name, tools:[{name, description, parameters}] }.
        // Non-Codex backends (Kiro/Claude) have no `namespace` type, so flatten each sub-tool
        // into a standalone Chat function (#1534). Without this the whole group collapsed into
        // one empty-schema function named `mcp__<server>__` and every MCP call failed with
        // `unsupported call: mcp__<server>__`.
        if (toolType === "namespace") {
          const nsName = toString(tool.name);
          const subTools = Array.isArray(tool.tools) ? tool.tools : [];
          return subTools
            .map((subValue) => toRecord(subValue))
            .filter((sub) => toString(sub.name))
            .map((sub) => {
              const leaf = toString(sub.name);
              // #8295: fold the namespace into the wire name so two namespaces
              // sharing a leaf (e.g. two MCP servers both exposing `_search`)
              // never collide into duplicate Chat tool names. Stamp the
              // identity for the response-side seam keyed on that qualified
              // wire name — qualified names cannot collide across namespaces,
              // so there is no ambiguity to detect/drop here anymore.
              const wireName = flattenNamespaceToolName(nsName, leaf);
              if (nsName && leaf) {
                namespaceToolIdentityMap.set(wireName, { namespace: nsName, name: leaf });
              }
              return {
                type: "function",
                function: {
                  name: wireName,
                  description: toString(sub.description),
                  parameters:
                    toString(sub.type) === "custom"
                      ? {
                          type: "object",
                          properties: { input: { type: "string" } },
                          required: ["input"],
                          additionalProperties: false,
                        }
                      : (sub.parameters ??
                        sub.input_schema ?? {
                          type: "object",
                          properties: {},
                        }),
                  strict: sub.strict,
                },
              };
            });
        }
        // tool_search (#2766) is a Responses API built-in Codex sends with
        // `execution: "client"` — the CLIENT (Codex CLI) resolves the call locally,
        // regardless of whether the wire format is Responses `{type:"tool_search"}` or
        // Chat `{type:"function"}`. Dropping it silently (as before) hid the tool from
        // the model entirely and broke Codex's lazy/deferred tool-loading protocol for
        // any provider downgraded to Chat Completions (#7532). Map it onto a normal
        // Chat function tool instead, mirroring the local_shell -> shell pattern below.
        if (TOOL_SEARCH_TOOL_TYPES.test(toolType)) {
          return {
            type: "function",
            function: {
              name: toString(tool.name) || "tool_search",
              description:
                toString(tool.description) || "Search for additional deferred tools by query.",
              parameters: tool.parameters ?? {
                type: "object",
                properties: {
                  query: {
                    type: "string",
                    description: "Natural-language or keyword query over available tools.",
                  },
                },
                required: ["query"],
              },
            },
          };
        }
        // Pass web_search server tools through with their original type (versioned or plain).
        // These have no Chat Completions equivalent; preserve as-is so upstreams that understand
        // Anthropic-style web_search_YYYYMMDD naming receive the exact name they expect.
        if (WEB_SEARCH_TOOL_TYPES.test(toolType)) {
          return toolValue;
        }
        // local_shell is a Responses API built-in (Codex CLI injects it for shell
        // execution). Non-OpenAI upstreams (Kiro/Claude) have no local_shell type,
        // so map it to a regular "shell" function tool. The response translator
        // already emits these as function_call, which Codex maps back to a shell call.
        if (toolType === "local_shell") {
          return {
            type: "function",
            function: {
              name: "shell",
              description: "Run a shell command and return its output.",
              parameters: {
                type: "object",
                properties: {
                  command: {
                    type: "array",
                    items: { type: "string" },
                    description: "Command and arguments to execute.",
                  },
                  workdir: { type: "string", description: "Working directory." },
                  timeout_ms: { type: "number", description: "Timeout in milliseconds." },
                },
                required: ["command"],
              },
            },
          };
        }
        // Responses API "hosted" tools (e.g. Codex's request_user_input,
        // { type: "request_user_input" }) carry no explicit `name` and cannot be
        // represented as a Chat Completions function declaration. Emitting them with
        // an empty name produces an anonymous functionDeclaration that downstream
        // providers such as Gemini reject with a 400 ("Invalid function name").
        // Skip any tool without a non-empty string name; named tools are unaffected.
        const name = tool.name;
        if (typeof name !== "string" || name.trim() === "") return [];

        // Custom/freeform tools (e.g. Codex apply_patch with type:"custom" and a grammar
        // format) carry no `parameters` field. Converting them to an empty function schema
        // makes downstream models invoke them with {}, but the Codex runtime expects
        // { input: string }. Normalize all custom tools to a well-defined { input: string }
        // schema so the model produces valid arguments. (#1007)
        if (toolType === "custom") {
          return {
            type: "function",
            function: {
              name: toString(tool.name),
              description: toString(tool.description),
              parameters: {
                type: "object",
                properties: {
                  input: { type: "string" },
                },
                required: ["input"],
                additionalProperties: false,
              },
              strict: tool.strict,
            },
          };
        }
        return {
          type: "function",
          function: {
            name,
            description: toString(tool.description),
            parameters: tool.parameters,
            strict: tool.strict,
          },
        };
      });
  }

  // Filter orphaned tool results (no matching tool_call in assistant messages)
  const allToolCallIds = new Set<string>();
  for (const m of messages) {
    const rec = toRecord(m);
    if (Array.isArray(rec.tool_calls)) {
      for (const tc of rec.tool_calls as { id?: string }[]) {
        if (tc.id) allToolCallIds.add(String(tc.id));
      }
    }
  }
  result.messages = messages.filter((m) => {
    const rec = toRecord(m);
    // #2893: drop ANY tool result whose tool_call_id has no matching tool_call —
    // including empty/missing ids (the previous `&& rec.tool_call_id` guard let
    // empty-id orphans slip through and triggered an upstream 400).
    if (rec.role === "tool") {
      return allToolCallIds.has(String(rec.tool_call_id ?? ""));
    }
    return true;
  });

  // Translate tool_choice object format: Responses {type,name} → Chat {type,function:{name}}
  if (
    result.tool_choice &&
    typeof result.tool_choice === "object" &&
    !Array.isArray(result.tool_choice)
  ) {
    const tc = toRecord(result.tool_choice);
    const tcType = toString(tc.type);
    if (tcType === "function" && tc.name !== undefined && !tc.function) {
      result.tool_choice = { type: "function", function: { name: tc.name } };
    } else if (tcType === "local_shell") {
      result.tool_choice = { type: "function", function: { name: "shell" } };
    } else if (tcType === "allowed_tools") {
      const mode = toString(tc.mode);
      if (mode !== "auto" && mode !== "required") {
        throw unsupportedFeature(
          `Unsupported Responses API feature: allowed_tools mode '${mode || "missing"}' is not supported by omniroute`
        );
      }
      if (!Array.isArray(tc.tools) || tc.tools.length === 0) {
        throw unsupportedFeature(
          "Unsupported Responses API feature: allowed_tools requires at least one function tool"
        );
      }

      const allowedNames = new Set<string>();
      for (const allowedValue of tc.tools) {
        const allowed = toRecord(allowedValue);
        const allowedType = toString(allowed.type);
        const allowedName = toString(allowed.name).trim();
        if (allowedType !== "function" || !allowedName) {
          throw unsupportedFeature(
            `Unsupported Responses API feature: allowed_tools descriptor type '${allowedType || "missing"}' cannot be represented in Chat Completions`
          );
        }
        allowedNames.add(allowedName);
      }

      const chatTools = Array.isArray(result.tools) ? result.tools : [];
      const availableNames = new Set(
        chatTools
          .map((toolValue) => toString(toRecord(toRecord(toolValue).function).name))
          .filter(Boolean)
      );
      const missingNames = [...allowedNames].filter((name) => !availableNames.has(name));
      if (missingNames.length > 0) {
        throw unsupportedFeature(
          `Unsupported Responses API feature: allowed_tools references unavailable function tool(s): ${missingNames.join(", ")}`
        );
      }

      // Keep the filtered array in a local: `result` is a Record<string, unknown>, so
      // reading `result.tools` back gives `unknown` and `.length` does not type-check.
      const allowedTools = chatTools.filter((toolValue) =>
        allowedNames.has(toString(toRecord(toRecord(toolValue).function).name))
      );
      result.tools = allowedTools;
      if (allowedTools.length === 0) {
        throw unsupportedFeature(
          "Unsupported Responses API feature: allowed_tools resolved to zero Chat Completions function tools"
        );
      }
      result.tool_choice = mode;
    } else if (tcType && tcType !== "function") {
      // Built-in tool types (web_search_preview, file_search, etc.) have no Chat equivalent
      throw unsupportedFeature(
        `Unsupported Responses API feature: tool_choice type '${tcType}' is not supported by omniroute`
      );
    }
  }

  // Cleanup Responses API specific fields
  // Note: prompt_cache_key is intentionally preserved for OpenAI destinations — it is
  // used by Codex as a cache-affinity signal and stripping it unconditionally broke
  // prompt caching (#517). But #517's fix never added a provider gate, so it leaked to
  // every destination, OpenAI or not — a strict non-OpenAI upstream (NVIDIA) 400s on the
  // unrecognized field (#7533). Strip it for any non-OpenAI destination.
  if (!isOpenAIDestination) delete result.prompt_cache_key;
  delete result.input;
  delete result.instructions;
  delete result.include;
  if (storeEnabled && root.store !== undefined) {
    result[RESPONSES_STORE_MARKER] = root.store;
  }
  delete result.store;

  // Promote Responses `reasoning.effort` to the Chat-Completions-native
  // `reasoning_effort` field so OpenAI-family upstreams (and the downstream
  // openai-to-claude translator's extended-thinking path) keep the hint when a
  // Responses client is routed across formats. The Copilot-only `summary` ->
  // Claude summarized-thinking marker stays behind the UA gate from
  // translateRequest because it is Copilot-specific glue, not an OpenAI-native
  // field. Ported from upstream PR decolua/9router#1817 (ryanngit).
  if (root.reasoning && typeof root.reasoning === "object" && !Array.isArray(root.reasoning)) {
    const reasoningRec = toRecord(root.reasoning);
    const effort = toString(reasoningRec.effort);
    if (effort && result.reasoning_effort === undefined) {
      result.reasoning_effort = normalizeResponsesReasoningEffort(effort);
    }
    if (
      credentialRecord._copilotClient === true &&
      shouldRequestClaudeSummarizedThinking(reasoningRec.summary)
    ) {
      result[COPILOT_REASONING_SUMMARY_MARKER] = "summarized";
    }
  }
  delete result.reasoning;
  // Strip Responses-API-only fields that Chat Completions rejects with 400.
  // safety_identifier is sent by LobeHub and has no Chat Completions equivalent (#2770).
  delete result.safety_identifier;
  // client_metadata is sent by Codex CLI and has no Chat Completions equivalent.
  // Strict upstreams (e.g. Mistral) reject it with HTTP 422 extra_forbidden.
  delete result.client_metadata;
  // truncation ("auto"/"disabled") is a Responses-API-only field with no Chat
  // Completions equivalent. Strict non-OpenAI upstreams (e.g. NVIDIA NIM) reject
  // it with HTTP 400 "Unsupported parameter(s): truncation" (#2311).
  delete result.truncation;
  // These fields configure Responses-owned state, caching, and tool execution limits.
  // Chat Completions has no equivalent and strict compatible endpoints reject them.
  delete result.max_tool_calls;
  delete result.conversation;
  delete result.prompt_cache_options;
  delete result.prompt_cache_retention;

  if (namespaceToolIdentityMap.size > 0) {
    // chatCore extracts and deletes this transient side channel before dispatch.
    // Non-enumerability keeps internal request metadata off the upstream wire.
    Object.defineProperty(result, "_toolNameMap", {
      value: namespaceToolIdentityMap,
      enumerable: false,
      configurable: true,
      writable: true,
    });
  }

  // Every Responses-API input — even a plain string — gets wrapped upstream as a
  // single-element content array (`[{ type: "input_text", text }]` via
  // normalizeResponsesInputForChat), which this function maps straight through to
  // `content: [{ type: "text", text }]`. That's spec-valid (OpenAI's own API
  // accepts both shapes) but several strict/naive OpenAI-compatible backends only
  // implement the plain-string form and reject the array form with a 500 — hit
  // live via AI Horde's Aphrodite facade rejecting every /v1/responses request,
  // including the simplest single-string input. A single-text-part array and a
  // plain string are semantically identical, so collapsing is safe there; real
  // multi-part messages (text+image, text+file) are left untouched. Scoped to
  // providers that declare `requiresPlainStringContent` — most OpenAI-compatible
  // backends (and several existing tests) expect the standard array shape to
  // survive translation unchanged.
  if (collapseToPlainString) {
    for (const message of messages) {
      const content = (message as JsonRecord).content;
      if (Array.isArray(content) && content.length === 1) {
        const part = content[0];
        if (
          part &&
          typeof part === "object" &&
          !Array.isArray(part) &&
          (part as JsonRecord).type === "text" &&
          typeof (part as JsonRecord).text === "string"
        ) {
          (message as JsonRecord).content = (part as JsonRecord).text;
        }
      }
    }
  }

  return result;
}

/**
 * `model` is sometimes a bare provider id (e.g. "aihorde"), sometimes a
 * provider-prefixed model string (e.g. "aihorde/aphrodite/..."), and often
 * null/a bare model id with no provider info at all (the generic translator
 * dispatcher passes model id alone; provider is tracked separately there).
 * Only the first two carry a usable provider hint.
 */
function extractProviderHint(model: unknown): string {
  if (typeof model !== "string" || model.length === 0) return "";
  if (getRegisteredProviders().includes(model)) return model;
  const prefix = model.split("/")[0];
  return getRegisteredProviders().includes(prefix) ? prefix : "";
}

// Register both directions
register(FORMATS.OPENAI_RESPONSES, FORMATS.OPENAI, openaiResponsesToOpenAIRequest, null);
register(FORMATS.OPENAI, FORMATS.OPENAI_RESPONSES, openaiToOpenAIResponsesRequest, null);

type JsonRecord = Record<string, unknown>;
const CLAUDE_CODE_COMPATIBLE_PROVIDER_PREFIX = "anthropic-compatible-cc-";

import { normalizeExcludedModelPatterns } from "@/domain/connectionModelRules";
import { normalizeRoutingTags } from "@/domain/tagRouter";
import { normalizeOpenRouterPreset } from "@/shared/constants/openRouterPreset";

export const CODEX_REASONING_EFFORT_VALUES = [
  "none",
  "low",
  "medium",
  "high",
  "xhigh",
  "max",
] as const;

export type CodexReasoningEffort = (typeof CODEX_REASONING_EFFORT_VALUES)[number];

const CODEX_REASONING_EFFORT_SET = new Set<string>(CODEX_REASONING_EFFORT_VALUES);

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function normalizeString(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const normalized = value.trim().toLowerCase();
  return normalized || undefined;
}

const BEDROCK_REGION_PATTERN = /^[a-z]{2}(?:-gov)?-[a-z]+-\d+$/i;

function normalizeAwsRegion(value: unknown): string | undefined {
  const normalized = normalizeString(value);
  if (!normalized || !BEDROCK_REGION_PATTERN.test(normalized)) return undefined;
  return normalized;
}

function hasNonEmptyString(value: unknown): boolean {
  return typeof value === "string" && value.trim().length > 0;
}

function isClaudeCodeCompatibleProvider(provider: string | null | undefined): boolean {
  return (
    typeof provider === "string" && provider.startsWith(CLAUDE_CODE_COMPATIBLE_PROVIDER_PREFIX)
  );
}

export function normalizeCodexReasoningEffort(value: unknown): CodexReasoningEffort | undefined {
  const normalized = normalizeString(value);
  if (!normalized || !CODEX_REASONING_EFFORT_SET.has(normalized)) {
    return undefined;
  }
  return normalized as CodexReasoningEffort;
}

export type CodexServiceTier = "default" | "priority" | "flex";

export function normalizeCodexServiceTier(value: unknown): CodexServiceTier | undefined {
  const normalized = normalizeString(value);
  if (!normalized) return undefined;
  if (normalized === "fast" || normalized === "priority") return "priority";
  if (normalized === "default" || normalized === "flex") return normalized;
  return undefined;
}

export function normalizeClaudeCodeCompatibleContext1m(value: unknown): true | undefined {
  return value === true ? true : undefined;
}

export function normalizeClaudeCodeCompatibleRedactThinking(value: unknown): true | undefined {
  return value === true ? true : undefined;
}

export function normalizeClaudeCodeCompatibleSummarizeThinking(value: unknown): true | undefined {
  return value === true ? true : undefined;
}

export function normalizeRequestDefaults(
  provider: string | null | undefined,
  value: unknown
): JsonRecord | undefined {
  const record = asRecord(value);
  if (Object.keys(record).length === 0) return undefined;

  const normalized: JsonRecord = { ...record };

  if (provider === "codex") {
    const reasoningEffort = normalizeCodexReasoningEffort(record.reasoningEffort);
    if (reasoningEffort) {
      normalized.reasoningEffort = reasoningEffort;
    } else {
      delete normalized.reasoningEffort;
    }

    const serviceTier = normalizeCodexServiceTier(record.serviceTier);
    if (serviceTier) {
      normalized.serviceTier = serviceTier;
    } else {
      delete normalized.serviceTier;
    }
  }

  if (isClaudeCodeCompatibleProvider(provider)) {
    const context1m = normalizeClaudeCodeCompatibleContext1m(record.context1m);
    if (context1m) {
      normalized.context1m = true;
    } else {
      delete normalized.context1m;
    }

    const redactThinking = normalizeClaudeCodeCompatibleRedactThinking(record.redactThinking);
    if (redactThinking) {
      normalized.redactThinking = true;
    } else {
      delete normalized.redactThinking;
    }

    const summarizeThinking = normalizeClaudeCodeCompatibleSummarizeThinking(
      record.summarizeThinking
    );
    if (summarizeThinking) {
      normalized.summarizeThinking = true;
    } else {
      delete normalized.summarizeThinking;
    }
  }

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

const CACHE_PASSTHROUGH_VALUES = new Set(["strip", "openai-format", "claude-format"]);

// #6880 — per-connection prompt-cache capability override: strip unknown keys / invalid
// types, drop the sub-object entirely when nothing valid survives.
export function normalizeCacheOverride(value: unknown): JsonRecord | undefined {
  const record = asRecord(value);
  if (Object.keys(record).length === 0) return undefined;

  const normalized: JsonRecord = {};
  if (typeof record.supportsPromptCaching === "boolean") {
    normalized.supportsPromptCaching = record.supportsPromptCaching;
  }
  if (
    typeof record.cacheControlPassthrough === "string" &&
    CACHE_PASSTHROUGH_VALUES.has(record.cacheControlPassthrough)
  ) {
    normalized.cacheControlPassthrough = record.cacheControlPassthrough;
  }

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

// #6880 — extracted so normalizeProviderSpecificData() stays under the
// max-lines-per-function gate: normalizes the two nested-object sub-fields
// (requestDefaults, cache) in one pass.
function normalizeNestedSubObjects(
  provider: string | null | undefined,
  normalized: JsonRecord
): void {
  if ("requestDefaults" in normalized) {
    const requestDefaults = normalizeRequestDefaults(provider, normalized.requestDefaults);
    if (requestDefaults) {
      normalized.requestDefaults = requestDefaults;
    } else {
      delete normalized.requestDefaults;
    }
  }

  if ("cache" in normalized) {
    const cache = normalizeCacheOverride(normalized.cache);
    if (cache) {
      normalized.cache = cache;
    } else {
      delete normalized.cache;
    }
  }
}

export function normalizeProviderSpecificData(
  provider: string | null | undefined,
  value: unknown
): JsonRecord | undefined {
  const record = asRecord(value);
  if (Object.keys(record).length === 0) return undefined;

  const normalized: JsonRecord = { ...record };

  normalizeNestedSubObjects(provider, normalized);

  if ("openaiStoreEnabled" in normalized && typeof normalized.openaiStoreEnabled !== "boolean") {
    delete normalized.openaiStoreEnabled;
  }

  if ("blockExtraUsage" in normalized && typeof normalized.blockExtraUsage !== "boolean") {
    delete normalized.blockExtraUsage;
  }

  // #2997: per-connection transient-cooldown opt-out — only persist a real boolean.
  if ("disableCooling" in normalized && typeof normalized.disableCooling !== "boolean") {
    delete normalized.disableCooling;
  }

  if ("autoFetchModels" in normalized && typeof normalized.autoFetchModels !== "boolean") {
    delete normalized.autoFetchModels;
  }

  if ("preset" in normalized) {
    const preset = provider === "openrouter" ? normalizeOpenRouterPreset(normalized.preset) : null;
    if (preset) {
      normalized.preset = preset;
    } else {
      delete normalized.preset;
    }
  }

  if (provider === "bedrock" && "region" in normalized) {
    const region = normalizeAwsRegion(normalized.region);
    if (region) {
      normalized.region = region;
    } else {
      delete normalized.region;
    }
  }

  if ("tag" in normalized) {
    if (typeof normalized.tag === "string") {
      const trimmedTag = normalized.tag.trim();
      if (trimmedTag) {
        normalized.tag = trimmedTag;
      } else {
        delete normalized.tag;
      }
    } else {
      delete normalized.tag;
    }
  }

  if ("tags" in normalized) {
    const tags = normalizeRoutingTags(normalized.tags);
    if (tags.length > 0) {
      normalized.tags = tags;
    } else {
      delete normalized.tags;
    }
  }

  if ("excludedModels" in normalized || "excluded_models" in normalized) {
    const excludedModels = normalizeExcludedModelPatterns(
      normalized.excludedModels ?? normalized.excluded_models
    );
    if (excludedModels.length > 0) {
      normalized.excludedModels = excludedModels;
    } else {
      delete normalized.excludedModels;
    }
    delete normalized.excluded_models;
  }

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

export function sanitizeProviderSpecificDataForResponse(value: unknown): JsonRecord | undefined {
  const record = asRecord(value);
  if (Object.keys(record).length === 0) return undefined;

  const sanitized: JsonRecord = { ...record };
  delete sanitized.consoleApiKey;
  delete sanitized.secretAccessKey;
  delete sanitized.awsSecretAccessKey;
  delete sanitized.sessionToken;
  delete sanitized.awsSessionToken;
  delete sanitized.openCodeGoAuthCookie;
  delete sanitized.opencodeGoAuthCookie;
  delete sanitized.authCookie;
  delete sanitized.ollamaUsageCookie;
  delete sanitized.ollamaCloudUsageCookie;
  delete sanitized.ollamaCloudCookie;
  delete sanitized.usageCookie;
  return sanitized;
}

export function isOpenAIResponsesStoreEnabled(providerSpecificData: unknown): boolean {
  return asRecord(providerSpecificData).openaiStoreEnabled === true;
}

export function buildOpenAIStoreSessionId(sessionId: unknown): string | undefined {
  if (!hasNonEmptyString(sessionId)) return undefined;

  const normalized = String(sessionId)
    .trim()
    .replace(/^ext:/i, "")
    .replace(/[^a-zA-Z0-9._:-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 96);

  if (!normalized) return undefined;
  return `omniroute-session-${normalized}`;
}

export function ensureOpenAIStoreSessionFallback(
  body: Record<string, unknown>,
  sessionId: unknown
): Record<string, unknown> {
  const explicitSessionId = body.session_id;
  const explicitConversationId = body.conversation_id;
  const promptCacheKey = body.prompt_cache_key ?? body.promptCacheKey;

  if (
    hasNonEmptyString(explicitSessionId) ||
    hasNonEmptyString(explicitConversationId) ||
    hasNonEmptyString(promptCacheKey)
  ) {
    return body;
  }

  const fallbackSessionId = buildOpenAIStoreSessionId(sessionId);
  if (!fallbackSessionId) return body;

  return {
    ...body,
    session_id: fallbackSessionId,
  };
}

export function getProviderRequestDefaults(
  provider: string | null | undefined,
  providerSpecificData: unknown
): JsonRecord {
  return normalizeRequestDefaults(provider, asRecord(providerSpecificData).requestDefaults) || {};
}

export function getCodexRequestDefaults(providerSpecificData: unknown): {
  reasoningEffort?: CodexReasoningEffort;
  serviceTier?: CodexServiceTier;
} {
  const defaults = getProviderRequestDefaults("codex", providerSpecificData);
  const reasoningEffort = normalizeCodexReasoningEffort(defaults.reasoningEffort);
  const serviceTier = normalizeCodexServiceTier(defaults.serviceTier);
  return {
    ...(reasoningEffort ? { reasoningEffort } : {}),
    ...(serviceTier ? { serviceTier } : {}),
